const NAV=[['dashboard','Beranda'],['products','DB Produk'],['boxes','DB Box'],['orders','Order'],['completed','Produk Selesai'],['inventory','Stok Produk'],['workers','DB Pekerja'],['settings','Pengaturan']];
const todayCode=()=>{const d=new Date();return String(d.getFullYear()).slice(2)+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0')};
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=n=>Number(n||0).toLocaleString('id-ID');
const money=n=>`Rp ${fmt(n)}`;
const blank={products:[],boxes:[],orders:[],completed:[],shipments:[],inventory:[],workers:[],groups:['PLATE','PLATEBOARD','TRAY'],loginUsers:[],adminConfig:[],logs:[]};
const demo={...blank,workers:[{id:'w1',name:'Budi',workplace:'Pandaan',phone:'0812-0000-0000',note:'',completed:[]}],loginUsers:[{id:'lu1',name:'Budi',active:true}],adminConfig:[{id:'admin',passwordHash:'3ef58410b868298fcca4ee41144221bf86bc94e810dfdac6f4b502ce5fcd75c6'}],products:[{id:'p1',name:'Sample Plate',w:250,d:250,h:20,weight_g:450,cbm:0.00125,wood:'Mahogany',finish:'Oil',unitPrice:35000,makers:[{workerId:'w1',price:35000}],parts:[{name:'Handle',size:'80x20x15',qty:2}],image:''}],boxes:[{id:'b1',w:510,d:160,h:260,price:12000,qty:40,weight_g:650,workplace:'Pandaan',phone:'0812-0000-0000',productIds:['p1']}],orders:[],completed:[],shipments:[],inventory:[],groups:['PLATE','PLATEBOARD','TRAY'],logs:[]};
const CFG=window.NAYESO_CONFIG||{};
const storedSettings=JSON.parse(localStorage.getItem('nayeso_id_settings')||'{}');
const initialSettings={url:CFG.SUPABASE_URL||storedSettings.url||'',key:CFG.SUPABASE_ANON_KEY||storedSettings.key||'',driveUrl:CFG.GOOGLE_DRIVE_GATEWAY_URL||storedSettings.driveUrl||'',driveToken:CFG.GOOGLE_DRIVE_GATEWAY_TOKEN||storedSettings.driveToken||''};
let S={page:'dashboard',productView:'detail',pageSize:20,data:null,supabase:null,cloud:false,syncTimer:null,cloudPollTimer:null,user:null,profile:null,sessionRole:null,actorName:'',settings:initialSettings,selectedProducts:new Set(),selectedBoxes:new Set(),selectedOrders:new Set(),selectedCompleted:new Set(),selectedInventory:new Set(),selectedWorkers:new Set(),selectedGroups:new Set(),productSort:'name',productGroupFilter:'all',baseData:null,localDirty:false,pendingRemote:null,syncing:false,remoteUpdatedAt:null};
function normalize(){
  for(const k of Object.keys(blank))if(!Array.isArray(S.data[k]))S.data[k]=JSON.parse(JSON.stringify(blank[k]));
  for(const p of S.data.products){
    p.parts=(p.parts||[]).map(x=>({...x,qty:+x.qty||1}));p.makers=p.makers||[];
    p.weight_g=+p.weight_g||0;p.cbm=+p.cbm||((+p.w||0)*(+p.d||0)*(+p.h||0)/1e9)||0;p.unitPrice=+p.unitPrice||0;
    p.group=p.group||'';p.imageFileName=p.imageFileName||'';p.imageSource=p.imageSource||'';p.details=Array.isArray(p.details)?p.details:[];p.detailHtml=typeof p.detailHtml==='string'?p.detailHtml:'';
  }
  for(const b of S.data.boxes){b.qty=+b.qty||0;b.weight_g=+b.weight_g||0}
  for(const o of S.data.orders){o.items=(o.items||[]).map(i=>({...i,qty:+i.qty||0,note:i.note||''})).filter(i=>i.productId&&i.qty>0);if(!o.items.length&&o.archived===undefined)o.archived=false}
  for(const c of S.data.completed){if(!c.group){const pp=S.data.products.find(p=>p.id===c.productId);c.group=pp?.group||''}c.totalQty=+c.totalQty||0;c.orderQty=+c.orderQty||0;c.unitPrice=+c.unitPrice||0;c.amount=+c.amount||(+c.totalQty||0)*(+c.unitPrice||0);c.consumedQty=+c.consumedQty||Math.min(+c.totalQty||0,+c.orderQty||0);c.totalWeightG=+c.totalWeightG||0;c.totalCbm=+c.totalCbm||0;c.boxCount=+c.boxCount||0;c.perBox=+c.perBox||0;c.boxId=c.boxId||''}
  for(const sh of S.data.shipments){sh.items=Array.isArray(sh.items)?sh.items:[];sh.shipCode=sh.shipCode||todayCode();sh.shippedAt=sh.shippedAt||new Date().toISOString()}
  if(!S.data.adminConfig.length)S.data.adminConfig=[{id:'admin',passwordHash:'3ef58410b868298fcca4ee41144221bf86bc94e810dfdac6f4b502ce5fcd75c6'}];
  S.data.loginUsers=S.data.loginUsers.map(x=>({id:x.id||uid(),name:String(x.name||'').trim(),active:x.active!==false})).filter(x=>x.name);
  purgeOldLogs();
}
function load(){try{S.data=JSON.parse(localStorage.getItem('nayeso_id_data'))||JSON.parse(JSON.stringify(demo))}catch{S.data=JSON.parse(JSON.stringify(demo))}normalize()}
function saveLocal(){localStorage.setItem('nayeso_id_data',JSON.stringify(S.data))}
function cloneData(x){return JSON.parse(JSON.stringify(x))}
function setSync(t,state=''){for(const id of ['syncBadge','mobileSync']){const el=document.getElementById(id);if(el){el.textContent=t;el.dataset.state=state}}}
function currentActor(){return S.sessionRole==='worker'?(S.actorName||'Pekerja'):''}
function isAdmin(){return S.sessionRole==='admin'}
function purgeOldLogs(){if(!S.data?.logs)return;const cutoff=Date.now()-90*24*60*60*1000;S.data.logs=S.data.logs.filter(l=>new Date(l.at||0).getTime()>=cutoff).sort((a,b)=>String(b.at||'').localeCompare(String(a.at||''))).slice(0,500)}
async function hashText(text){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(text)));return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function adminHash(){return S.data.adminConfig?.find(x=>x.id==='admin')?.passwordHash||'3ef58410b868298fcca4ee41144221bf86bc94e810dfdac6f4b502ce5fcd75c6'}
function entityLabel(type,x){if(!x)return'';if(type==='products')return x.name||x.id;if(type==='boxes')return `${x.w||0}x${x.d||0}x${x.h||0} Box`;if(type==='orders')return x.orderNo||x.id;if(type==='completed')return prodName(x.productId)||x.id;if(type==='shipments')return x.shipCode||x.id;if(type==='inventory')return x.name||x.id;if(type==='workers'||type==='loginUsers')return x.name||x.id;return x.id||''}
function buildChangeDetail(label){try{const prev=JSON.parse(localStorage.getItem('nayeso_id_data')||'{}');const lines=[];for(const type of ['products','boxes','orders','completed','shipments','inventory','workers','loginUsers']){const a=Array.isArray(prev[type])?prev[type]:[],b=Array.isArray(S.data[type])?S.data[type]:[];const am=new Map(a.map(x=>[x.id,x])),bm=new Map(b.map(x=>[x.id,x]));const added=[...bm.keys()].filter(id=>!am.has(id));const removed=[...am.keys()].filter(id=>!bm.has(id));const changed=[...bm.keys()].filter(id=>am.has(id)&&JSON.stringify(am.get(id))!==JSON.stringify(bm.get(id)));if(added.length)lines.push(`${type}: tambah ${added.map(id=>entityLabel(type,bm.get(id))).join(', ')}`);if(removed.length)lines.push(`${type}: hapus ${removed.map(id=>entityLabel(type,am.get(id))).join(', ')}`);if(changed.length)lines.push(`${type}: ubah ${changed.map(id=>entityLabel(type,bm.get(id))).join(', ')}`)}if(JSON.stringify(prev.groups||[])!==JSON.stringify(S.data.groups||[]))lines.push('groups: daftar/urutan grup berubah');return lines.length?lines.join('\n'):label}catch{return label}}
function same(a,b){return JSON.stringify(a)===JSON.stringify(b)}
function mergeCollection(base,local,remote){
  const bm=new Map((base||[]).filter(x=>x&&x.id).map(x=>[x.id,x]));
  const lm=new Map((local||[]).filter(x=>x&&x.id).map(x=>[x.id,x]));
  const rm=new Map((remote||[]).filter(x=>x&&x.id).map(x=>[x.id,x]));
  for(const [id,b] of bm){if(!lm.has(id))rm.delete(id);else if(!same(lm.get(id),b))rm.set(id,lm.get(id))}
  for(const [id,l] of lm)if(!bm.has(id))rm.set(id,l);
  return [...rm.values()];
}
function mergeState(base,local,remote){
  base=base||cloneData(blank);remote=remote||cloneData(blank);const out=cloneData(remote);
  for(const k of ['products','boxes','orders','completed','shipments','inventory','workers','loginUsers','adminConfig'])out[k]=mergeCollection(base[k],local[k],remote[k]);
  if(!same(base.groups,local.groups))out.groups=cloneData(local.groups);
  const logs=new Map([...(remote.logs||[]),...(local.logs||[])].filter(x=>x?.id).map(x=>[x.id,x]));
  const cutoff=Date.now()-90*24*60*60*1000;out.logs=[...logs.values()].filter(x=>new Date(x.at||0).getTime()>=cutoff).sort((a,b)=>String(b.at||'').localeCompare(String(a.at||''))).slice(0,500);
  return out;
}
function dataUrlToBlob(dataUrl){const [h,b64]=dataUrl.split(',');const mime=(h.match(/data:([^;]+)/)||[])[1]||'image/jpeg';const bytes=atob(b64),arr=new Uint8Array(bytes.length);for(let i=0;i<bytes.length;i++)arr[i]=bytes.charCodeAt(i);return new Blob([arr],{type:mime})}
function driveConfig(){const a=S.data?.adminConfig?.find(x=>x.id==='admin')||{};return{url:(a.driveUrl||S.settings.driveUrl||'').trim(),token:(a.driveToken||S.settings.driveToken||'').trim()}}
function driveEnabled(){const d=driveConfig();return !!(d.url&&d.token)}
function driveFormRequest(action,data={}){return new Promise((resolve,reject)=>{const d=driveConfig();if(!d.url||!d.token)return reject(new Error('Google Drive belum dikonfigurasi'));const reqId='drv_'+uid(),iframe=document.createElement('iframe');iframe.name=reqId;iframe.style.display='none';document.body.appendChild(iframe);const form=document.createElement('form');form.method='POST';form.action=d.url;form.target=reqId;form.style.display='none';const inp=document.createElement('input');inp.name='payload';inp.value=JSON.stringify({reqId,token:d.token,action,...data});form.appendChild(inp);document.body.appendChild(form);let done=false;const cleanup=()=>{window.removeEventListener('message',onmsg);form.remove();setTimeout(()=>iframe.remove(),100)};const timer=setTimeout(()=>{if(done)return;done=true;cleanup();reject(new Error('Google Drive tidak merespons. Periksa deployment Apps Script.'))},45000);function onmsg(e){const r=e.data;if(!r||r.nayesoDrive!==true||r.reqId!==reqId)return;done=true;clearTimeout(timer);cleanup();r.ok?resolve(r):reject(new Error(r.error||'Google Drive gagal'))}window.addEventListener('message',onmsg);form.submit()})}
async function uploadImageToDrive(dataUrl,path){const m=String(dataUrl||'').match(/^data:([^;]+);base64,(.+)$/);if(!m) return dataUrl;const fileName=(path.split('/').pop()||('image-'+Date.now()+'.jpg')).replace(/[^a-zA-Z0-9._-]/g,'_');const folder=path.includes('/details/')?'Detail Images':'Product Images';const r=await driveFormRequest('upload',{folder,fileName,mime:m[1],base64:m[2]});return r.url||dataUrl}
async function uploadDataImage(dataUrl,path){if(!String(dataUrl||'').startsWith('data:image/'))return dataUrl;if(driveEnabled()){try{return await uploadImageToDrive(dataUrl,path)}catch(e){console.warn('Google Drive upload gagal',e)}}if(S.cloud&&S.supabase){try{const blob=dataUrlToBlob(dataUrl);const {error}=await S.supabase.storage.from('product-images').upload(path,blob,{upsert:true,contentType:blob.type,cacheControl:'3600'});if(error)throw error;const {data}=S.supabase.storage.from('product-images').getPublicUrl(path);return data.publicUrl||dataUrl}catch(e){console.warn('Supabase Storage upload gagal',e)}}return dataUrl}
async function migrateImagesToCloud(){if(!driveEnabled()&&!S.cloud)return false;let changed=false;for(const p of S.data.products){if(String(p.image||'').startsWith('data:image/')){const before=p.image;p.image=await uploadDataImage(p.image,`products/${p.id}/main-${Date.now()}.jpg`);if(p.image!==before){p.imageSource=driveEnabled()?'google-drive':'cloud';changed=true}}for(const d of (p.details||[])){if(d.type==='image'&&String(d.src||'').startsWith('data:image/')){const before=d.src;d.src=await uploadDataImage(d.src,`products/${p.id}/details/${d.id||uid()}-${Date.now()}.jpg`);if(d.src!==before)changed=true}}}if(changed)saveLocal();return changed}
async function syncCloudState(){
  if(!S.cloud||!S.supabase||S.syncing)return;S.syncing=true;clearTimeout(S.syncTimer);setSync('Menyinkronkan…','syncing');
  try{
    await migrateImagesToCloud();
    const {data:rows,error:readErr}=await S.supabase.from('app_state').select('data,updated_at').eq('id','main').limit(1);if(readErr)throw readErr;
    const row=Array.isArray(rows)?rows[0]:null;
    const remote=row?.data&&Object.keys(row.data).length?row.data:cloneData(blank);
    const merged=mergeState(S.baseData||remote,S.data,remote);normalizeFor(merged);
    const now=new Date().toISOString();const {error}=await S.supabase.from('app_state').upsert({id:'main',data:merged,updated_at:now});if(error)throw error;
    S.data=merged;S.baseData=cloneData(merged);S.remoteUpdatedAt=now;S.localDirty=false;S.pendingRemote=null;saveLocal();setSync('Tersinkron · real-time','ok');
  }catch(e){console.error(e);setSync('Sinkronisasi gagal · data tersimpan lokal','error')}finally{S.syncing=false}
}
function normalizeFor(d){const old=S.data;S.data=d;normalize();d=S.data;S.data=old;return d}
async function persist(label='Perubahan',detail=''){if(driveEnabled())await migrateImagesToCloud();const info=detail||buildChangeDetail(label);S.data.logs.unshift({id:uid(),at:new Date().toISOString(),label,detail:info,by:currentActor()});purgeOldLogs();saveLocal();if(S.cloud&&S.supabase){S.localDirty=true;setSync('Menyinkronkan…','syncing');clearTimeout(S.syncTimer);await syncCloudState()}}
function buildNav(){const navItems=isAdmin()?NAV:NAV.filter(([k])=>k!=='settings');document.getElementById('nav').innerHTML=navItems.map(([k,v])=>`<button data-page="${k}">${v}</button>`).join('');document.getElementById('nav').onclick=e=>{if(e.target.dataset.page){S.page=e.target.dataset.page;closeMobileMenu();render()}}}
async function init(){
  load();buildNav();restoreAppSession();
  document.getElementById('searchBox').oninput=()=>render();document.getElementById('excelFile').onchange=handleExcel;document.getElementById('productImageInput').onchange=productImagePicked;document.getElementById('productCameraInput').onchange=productImagePicked;
  // Service Worker disabled in Streamlit embedded mode.
  window.addEventListener('online',()=>{setSync('Online · sinkronisasi…','syncing');if(S.cloud){if(S.localDirty)syncCloudState();else refreshFromCloud()}});window.addEventListener('offline',()=>setSync('Offline · perubahan disimpan di perangkat','error'));
  if(S.settings.url&&S.settings.key)await connectCloud();else {S.cloud=false;setSync('Mode lokal · hosting diperlukan untuk sinkronisasi','error');renderLoginGateway()}
}
function restoreAppSession(){try{const x=JSON.parse(sessionStorage.getItem('nayeso_id_app_session')||'null');if(x?.role==='admin'){S.sessionRole='admin';S.actorName=''}else if(x?.role==='worker'&&x?.name){S.sessionRole='worker';S.actorName=x.name}}catch{}}
function saveAppSession(){sessionStorage.setItem('nayeso_id_app_session',JSON.stringify({role:S.sessionRole,name:S.actorName||''}))}
function clearAppSession(){sessionStorage.removeItem('nayeso_id_app_session');S.sessionRole=null;S.actorName=''}
function renderCloudSetup(){renderLoginGateway()}
async function firstCloudConnect(){}
function startCloudPolling(){
  clearInterval(S.cloudPollTimer);
  S.cloudPollTimer=setInterval(async()=>{
    if(!S.cloud||!S.supabase||S.localDirty||S.syncing||document.visibilityState==='hidden'||!navigator.onLine)return;
    try{
      const {data:states,error}=await S.supabase.from('app_state').select('data,updated_at').eq('id','main').limit(1);
      if(error)throw error;
      const state=Array.isArray(states)?states[0]:null;
      if(!state?.data)return;
      if(state.updated_at&&S.remoteUpdatedAt&&String(state.updated_at)<=String(S.remoteUpdatedAt))return;
      S.data=state.data;normalize();S.baseData=cloneData(S.data);S.remoteUpdatedAt=state.updated_at||new Date().toISOString();saveLocal();
      if(S.sessionRole)render();else renderLoginGateway();
      setSync('Data terbaru diterapkan','ok');
    }catch(e){console.warn('CLOUD_POLL_ERROR',e)}
  },2000);
}
function toggleMobileMenu(){const sb=document.querySelector('.sidebar'),bd=document.getElementById('mobileMenuBackdrop');if(!sb)return;const open=!sb.classList.contains('mobile-open');sb.classList.toggle('mobile-open',open);bd?.classList.toggle('show',open)}
function closeMobileMenu(){document.querySelector('.sidebar')?.classList.remove('mobile-open');document.getElementById('mobileMenuBackdrop')?.classList.remove('show')}
async function connectCloud(){
  const {url,key}=S.settings;if(!url||!key){S.cloud=false;renderLoginGateway();return}
  try{
    S.supabase=window.supabase.createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}});S.cloud=true;
    const {data:states,error}=await S.supabase.from('app_state').select('data,updated_at').eq('id','main').limit(1);if(error)throw error;
    const state=Array.isArray(states)?states[0]:null;
    if(state?.data&&Object.keys(state.data).length){S.data=state.data;normalize();S.baseData=cloneData(S.data);S.remoteUpdatedAt=state.updated_at;saveLocal()}else{await migrateImagesToCloud();await S.supabase.from('app_state').upsert({id:'main',data:S.data,updated_at:new Date().toISOString()});S.baseData=cloneData(S.data)}
    S.supabase.removeAllChannels();S.supabase.channel('nayeso-id-state').on('postgres_changes',{event:'*',schema:'public',table:'app_state',filter:'id=eq.main'},payload=>{if(!payload.new?.data)return;if(S.localDirty||S.syncing){S.pendingRemote=payload.new.data;setSync('Ada perubahan lain · menyinkronkan…','pending');return}S.data=payload.new.data;normalize();S.baseData=cloneData(S.data);S.remoteUpdatedAt=payload.new.updated_at;saveLocal();if(S.sessionRole)render();else renderLoginGateway();setSync('Perubahan terbaru diterapkan','ok')}).subscribe(status=>{if(status==='SUBSCRIBED')setSync('DB bersama aktif · real-time','ok')});
    startCloudPolling();
    if(S.sessionRole)render();else renderLoginGateway();
  }catch(e){console.error('SUPABASE_CONNECT_ERROR',e);S.cloud=false;setSync('Mode lokal','error');renderLoginGateway()}
}
async function refreshFromCloud(){if(!S.cloud||S.localDirty)return;const {data:states,error}=await S.supabase.from('app_state').select('data,updated_at').eq('id','main').limit(1);if(error){console.error(error);setSync('Gagal memuat cloud','error');return}const state=Array.isArray(states)?states[0]:null;if(state?.data){S.data=state.data;normalize();S.baseData=cloneData(S.data);S.remoteUpdatedAt=state.updated_at;saveLocal();if(S.sessionRole)render();else renderLoginGateway();setSync('Data terbaru dimuat','ok')}}
function renderLoginGateway(msg=''){
  document.getElementById('userBtn').classList.add('hidden');document.getElementById('searchBox').classList.add('hidden');meta('Login','Pilih jenis login');
  content.innerHTML=`<div class="login-shell"><div class="auth-card login-choice"><h2>SEMANGAT</h2><p class="note">Pilih cara masuk.</p>${msg?`<div class="alert">${esc(msg)}</div>`:''}<div class="login-choice-grid"><button class="login-big primary" onclick="renderWorkerLogin()"><b>Login Umum</b><span>Pekerja memilih nama lalu langsung masuk</span></button><button class="login-big secondary" onclick="renderAdminLogin()"><b>Login Admin</b><span>Pengaturan dan pengelolaan pengguna</span></button></div></div></div>`
}
function renderWorkerLogin(){meta('Login Umum','Pilih nama pekerja');const users=S.data.loginUsers.filter(x=>x.active!==false);content.innerHTML=`<div class="auth-card"><h2>Login Umum</h2><div class="field"><label>Nama Pekerja</label><select id="worker_login_name"><option value="">Pilih nama</option>${users.map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('')}</select></div><div class="toolbar" style="margin-top:14px"><button class="primary" onclick="doWorkerLogin()">Masuk</button><button class="secondary" onclick="renderLoginGateway()">Kembali</button></div>${users.length?'':'<p class="note">Belum ada nama login. Admin harus menambahkan nama terlebih dahulu.</p>'}</div>`}
function doWorkerLogin(){const name=worker_login_name.value;if(!name)return alert('Pilih nama pekerja.');if(!S.data.loginUsers.some(x=>x.name===name&&x.active!==false))return alert('Nama ini tidak aktif.');S.sessionRole='worker';S.actorName=name;saveAppSession();S.page='dashboard';render()}
function renderAdminLogin(msg=''){meta('Login Admin','Masukkan password Admin');content.innerHTML=`<div class="auth-card"><h2>Login Admin</h2>${msg?`<div class="alert">${esc(msg)}</div>`:''}<div class="field"><label>Password Admin</label><input id="admin_login_password" type="password" inputmode="numeric" autocomplete="current-password" onkeydown="if(event.key==='Enter')doAdminLogin()"></div><div class="toolbar" style="margin-top:14px"><button class="primary" onclick="doAdminLogin()">Masuk</button><button class="secondary" onclick="renderLoginGateway()">Kembali</button></div></div>`;setTimeout(()=>admin_login_password?.focus(),30)}
async function doAdminLogin(){const h=await hashText(admin_login_password.value);if(h!==adminHash())return renderAdminLogin('Password salah.');S.sessionRole='admin';S.actorName='';saveAppSession();S.page='dashboard';render()}
function logout(){clearAppSession();document.getElementById('searchBox').classList.add('hidden');renderLoginGateway()}
function openAccountMenu(){modalBody.innerHTML=`<h2>${isAdmin()?'Admin':'Pekerja'}</h2>${isAdmin()?'<p class="note">Mode Admin</p>':`<p><b>${esc(S.actorName)}</b></p>`}<button class="secondary" onclick="logout();closeModal()">Keluar</button>`;openModal()}
function renderAuth(msg=''){renderLoginGateway(msg)}
