function meta(title,sub){document.getElementById('pageTitle').textContent=title;document.getElementById('pageSub').textContent=sub;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===S.page))}
function render(){if(!S.sessionRole){renderLoginGateway();return}if(!isAdmin()&&S.page==='settings')S.page='dashboard';buildNav();document.getElementById('searchBox').classList.remove('hidden');document.getElementById('userBtn').classList.remove('hidden');document.getElementById('userBtn').textContent=isAdmin()?'Admin':S.actorName;const q=(document.getElementById('searchBox').value||'').toLowerCase();const fns={dashboard:renderDashboard,products:()=>renderProducts(q),boxes:()=>renderBoxes(q),orders:()=>renderOrders(q),completed:()=>renderCompleted(q),inventory:()=>renderInventory(q),workers:()=>renderWorkers(q),settings:renderSettings};fns[S.page]()}
function renderDashboard(){meta('Beranda','Produk · box · order · hasil produksi dalam satu tempat');const orderKinds=new Set(),completedKinds=new Set();let orderQty=0,completedQty=0;S.data.orders.filter(o=>!o.archived).forEach(o=>o.items.forEach(i=>{orderKinds.add(i.productId);orderQty+=+i.qty||0}));S.data.completed.forEach(c=>{completedKinds.add(c.productId);completedQty+=+c.totalQty||0});content.innerHTML=`<div class="grid grid4"><div class="card metric"><small>DB Produk</small><strong>${S.data.products.length}</strong><div class="sub">Jumlah jenis produk</div></div><div class="card metric"><small>DB Box</small><strong>${S.data.boxes.length}</strong><div class="sub">Jumlah jenis box</div></div><div class="card metric"><small>Order</small><strong>${orderKinds.size} jenis / ${fmt(orderQty)} pcs</strong><div class="sub">Jenis produk / total pcs</div></div><div class="card metric"><small>Produk Selesai</small><strong>${completedKinds.size} jenis / ${fmt(completedQty)} pcs</strong><div class="sub">Jenis / total pcs</div></div></div><div class="grid grid2" style="margin-top:14px"><div class="card"><h3>Produk Terbaru</h3><div class="dashboard-products">${S.data.products.slice(0,3).map(p=>`<div class="dashboard-product" onclick="openProduct('${p.id}')">${imgTag(p,'thumb')}<div style="margin-top:7px"><b>${esc(p.name)}</b><div class="note">${esc(p.wood||'')} · ${esc(p.finish||'')}</div></div></div>`).join('')||'<div class="note">Belum ada produk.</div>'}</div></div><div class="card"><h3>Akses Cepat</h3><div class="quick-grid"><button class="secondary" onclick="openProduct()">+ Tambah Produk</button><button class="secondary" onclick="openBulkImport()">Excel + Gambar Massal</button><button class="secondary" onclick="S.page='boxes';render()">DB Box</button><button class="secondary" onclick="S.page='orders';render()">Buat / Lihat Order</button><button class="secondary" onclick="S.page='completed';render()">Produk Selesai</button><button class="secondary" onclick="S.page='inventory';render()">Stok Produk</button></div></div></div>`}
function prodName(id){return S.data.products.find(p=>p.id===id)?.name||'-'}
function workerName(id){return S.data.workers.find(w=>w.id===id)?.name||'-'}
function imgTag(p,cls='thumb'){return p?.image?`<img class="${cls}" src="${esc(p.image)}" alt="">`:`<div class="${cls} noimg">Tanpa Gambar</div>`}
function productSize(p){return `${p?.w||0}x${p?.d||0}x${p?.h||0}`}
function priceForWorker(p,workerId){return +(p?.makers||[]).find(m=>m.workerId===workerId)?.price||+p?.unitPrice||0}
function toggleProduct(id,checked){checked?S.selectedProducts.add(id):S.selectedProducts.delete(id)}
function clearProductSelection(){S.selectedProducts.clear();render()}
function selectVisibleProducts(){S.data.products.filter(p=>JSON.stringify(p).toLowerCase().includes((document.getElementById('searchBox').value||'').toLowerCase())).slice(0,S.pageSize).forEach(p=>S.selectedProducts.add(p.id));render()}
async function moveSelectedProducts(dir){if(!S.selectedProducts.size)return alert('Pilih produk yang akan dipindahkan.');const a=S.data.products;if(dir<0){for(let i=1;i<a.length;i++)if(S.selectedProducts.has(a[i].id)&&!S.selectedProducts.has(a[i-1].id))[a[i-1],a[i]]=[a[i],a[i-1]]}else{for(let i=a.length-2;i>=0;i--)if(S.selectedProducts.has(a[i].id)&&!S.selectedProducts.has(a[i+1].id))[a[i],a[i+1]]=[a[i+1],a[i]]}await persist('Urutan produk diubah');render()}
async function deleteSelectedProducts(){if(!S.selectedProducts.size)return alert('Pilih produk yang akan dihapus.');if(!confirm(`Hapus ${S.selectedProducts.size} produk yang dipilih?`))return;const ids=new Set(S.selectedProducts);S.data.products=S.data.products.filter(p=>!ids.has(p.id));S.data.inventory=S.data.inventory.filter(x=>!ids.has(x.productId));S.selectedProducts.clear();await persist('Produk terpilih dihapus');render()}
function toggleSelection(kind,id,checked){const set=S[kind];if(!set)return;checked?set.add(id):set.delete(id);render()}
function clearSelection(kind){S[kind]?.clear();render()}
function setVisibleSelection(kind,items,checked){const set=S[kind];if(!set)return;for(const x of items)checked?set.add(x.id):set.delete(x.id);render()}
async function deleteSelectedBoxes(){if(!S.selectedBoxes.size)return alert('Pilih box yang akan dihapus.');if(!confirm(`Hapus ${S.selectedBoxes.size} data box yang dipilih?`))return;const ids=new Set(S.selectedBoxes);S.data.boxes=S.data.boxes.filter(x=>!ids.has(x.id));S.selectedBoxes.clear();await persist('DB Box terpilih dihapus');render()}
async function deleteSelectedOrders(){if(!S.selectedOrders.size)return alert('Pilih order yang akan dihapus.');if(!confirm(`Hapus ${S.selectedOrders.size} order dari daftar aktif? Order yang dihapus tidak akan muncul sebagai kandidat Produk Selesai.`))return;for(const o of S.data.orders)if(S.selectedOrders.has(o.id))o.archived=true;S.selectedOrders.clear();await persist('Order terpilih dihapus dari daftar aktif');render()}
async function deleteSelectedInventory(){if(!S.selectedInventory.size)return alert('Pilih stok yang akan dihapus.');if(!confirm(`Hapus ${S.selectedInventory.size} data stok yang dipilih?`))return;const ids=new Set(S.selectedInventory);S.data.inventory=S.data.inventory.filter(x=>!ids.has(x.id));S.selectedInventory.clear();await persist('Stok terpilih dihapus');render()}
async function deleteSelectedWorkers(){if(!S.selectedWorkers.size)return alert('Pilih pekerja yang akan dihapus.');const activeRefs=S.data.orders.filter(o=>!o.archived&&S.selectedWorkers.has(o.workerId));if(activeRefs.length)return alert('Ada pekerja terpilih yang masih memiliki Order aktif. Selesaikan atau hapus Order tersebut terlebih dahulu.');if(!confirm(`Hapus ${S.selectedWorkers.size} pekerja yang dipilih? Data produsen pada DB Produk juga akan dilepas.`))return;const ids=new Set(S.selectedWorkers);S.data.workers=S.data.workers.filter(x=>!ids.has(x.id));for(const p of S.data.products)p.makers=(p.makers||[]).filter(m=>!ids.has(m.workerId));S.selectedWorkers.clear();await persist('Pekerja terpilih dihapus');render()}
async function deleteSelectedCompleted(){if(!S.selectedCompleted.size)return alert('Pilih Produk Selesai yang akan dihapus.');const rows=S.data.completed.filter(c=>S.selectedCompleted.has(c.id));if(!rows.length)return;if(!confirm(`Hapus ${rows.length} Produk Selesai yang dipilih? Qty masing-masing akan kembali ke Order dan stok Box akan otomatis dikembalikan.`))return;for(const c of rows){restoreCompletionToOrder(c);restoreBoxStock(c)}const ids=new Set(rows.map(x=>x.id));S.data.completed=S.data.completed.filter(x=>!ids.has(x.id));S.selectedCompleted.clear();await persist('Produk Selesai terpilih dihapus · qty Order & stok Box dikembalikan');render()}
function renderProducts(q=''){meta('DB Produk','Cari menurut nama / grup · urutkan nama atau grup + nama');let arr=S.data.products.filter(p=>JSON.stringify(p).toLowerCase().includes(q)&&(S.productGroupFilter==='all'||(p.group||'')===S.productGroupFilter));const byName=(a,b)=>String(a.name||'').localeCompare(String(b.name||''),'id',{numeric:true,sensitivity:'base'}),byGroup=(a,b)=>String(a.group||'').localeCompare(String(b.group||''),'id',{numeric:true,sensitivity:'base'});if(S.productSort==='group')arr.sort(byGroup);else if(S.productSort==='groupName')arr.sort((a,b)=>byGroup(a,b)||byName(a,b));else arr.sort(byName);arr=arr.slice(0,S.pageSize);const controls=`<div class="toolbar no-print"><button class="secondary" onclick="selectVisibleProducts()">Pilih Semua</button><button class="secondary" onclick="clearProductSelection()">Batal Pilih</button><button class="secondary" onclick="moveSelectedProducts(-1)">↑ Naik</button><button class="secondary" onclick="moveSelectedProducts(1)">↓ Turun</button><button class="danger" onclick="deleteSelectedProducts()">Hapus Pilihan</button><span class="spacer"></span><label>Grup <select onchange="S.productGroupFilter=this.value;render()"><option value="all" ${S.productGroupFilter==='all'?'selected':''}>Semua Grup</option>${S.data.groups.map(g=>`<option value="${esc(g)}" ${S.productGroupFilter===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label><label>Urutkan <select onchange="S.productSort=this.value;render()"><option value="name" ${S.productSort==='name'?'selected':''}>Nama</option><option value="group" ${S.productSort==='group'?'selected':''}>Grup</option><option value="groupName" ${S.productSort==='groupName'?'selected':''}>Grup + Nama</option></select></label><div class="tabs"><button class="${S.productView==='detail'?'active':''}" onclick="S.productView='detail';render()">Gambar + Detail</button><button class="${S.productView==='name'?'active':''}" onclick="S.productView='name';render()">Gambar + Nama</button><button class="${S.productView==='image'?'active':''}" onclick="S.productView='image';render()">Gambar</button></div><select onchange="S.pageSize=+this.value;render()">${[10,20,50,100].map(n=>`<option ${n===S.pageSize?'selected':''}>${n}</option>`).join('')}</select><button class="secondary" onclick="exportExcel('products')">Excel</button><button class="secondary" onclick="printProducts()">PDF / Print</button><button class="primary" onclick="openProduct()">+ Tambah Produk</button></div>`;let body='';if(S.productView==='detail')body=`<div class="product-list">${arr.map(p=>`<div class="product-row product-row-select"><div><input class="row-check" type="checkbox" ${S.selectedProducts.has(p.id)?'checked':''} onchange="toggleProduct('${p.id}',this.checked)"></div><div onclick="openProduct('${p.id}')">${imgTag(p)}</div><div onclick="openProduct('${p.id}')"><b>${esc(p.name)}</b> ${p.group?`<span class="badge">${esc(p.group)}</span>`:''}<div class="note">${esc(p.wood)} · ${esc(p.finish)}</div><div class="note">${productSize(p)} mm · ${fmt(p.weight_g||0)} g · CBM ${Number(p.cbm||0).toFixed(6)}</div><div class="note">${p.parts?.length||0} komponen tambahan · ${p.details?.length||0} detail</div></div><div class="row-actions" onclick="openProduct('${p.id}')"><span class="badge">Produsen ${p.makers?.length||0}</span></div></div>`).join('')}</div>`;else body=`<div class="gallery">${arr.map(p=>`<div class="gallery-card gallery-select"><div class="card-check"><input class="row-check" type="checkbox" ${S.selectedProducts.has(p.id)?'checked':''} onchange="toggleProduct('${p.id}',this.checked)"></div><div onclick="openProduct('${p.id}')">${imgTag(p,'gallery-img')}${S.productView==='name'?`<div class="info"><b>${esc(p.name)}</b>${p.group?`<div><span class="badge">${esc(p.group)}</span></div>`:''}</div>`:''}</div></div>`).join('')}</div>`;content.innerHTML=controls+body}
function compressImageFile(file,max=1400,quality=.82){return new Promise(res=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{let w=img.width,h=img.height;if(Math.max(w,h)>max){const k=max/Math.max(w,h);w=Math.round(w*k);h=Math.round(h*k)}const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);const preserveAlpha=/image\/(png|webp)/i.test(file.type||'');res(c.toDataURL(preserveAlpha?'image/png':'image/jpeg',quality))};img.onerror=()=>res(r.result);img.src=r.result};r.onerror=()=>res('');r.readAsDataURL(file)})}
function chooseProductImage(){window._productImageSource='gallery';productImageInput.value='';productImageInput.click()}
function takeProductPhoto(){window._productImageSource='camera';productCameraInput.value='';productCameraInput.click()}
function mobileImageName(prefix='MOBILE'){const d=new Date(),pad=n=>String(n).padStart(2,'0');return `${prefix}_${String(d.getFullYear()).slice(2)}${pad(d.getMonth()+1)}${pad(d.getDate())}_${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}.jpg`}
async function productImagePicked(e){const f=e.target.files?.[0];if(!f)return;window._pendingProductImage=await compressImageFile(f);window._pendingProductImageSource=window._productImageSource||'gallery';window._pendingProductImageFileName=window._pendingProductImageSource==='camera'?mobileImageName('MOBILE'):f.name;const pr=document.getElementById('productImagePreview');if(pr){pr.src=window._pendingProductImage;pr.classList.remove('hidden')}const no=document.getElementById('productNoImage');if(no)no.classList.add('hidden');const fn=document.getElementById('productImageFileName');if(fn)fn.textContent=window._pendingProductImageFileName||''}
function legacyDetailsToHtml(details=[]){return (details||[]).map(d=>d.type==='image'?`<p><img src="${esc(d.src||'')}" style="max-width:100%;width:60%;height:auto"><br><span>${esc(d.note||'')}</span></p>`:`<p>${esc(d.text||'').replace(/\n/g,'<br>')}</p>`).join('')}
function detailEditorInitialHtml(p){return (p.detailHtml&&String(p.detailHtml).trim())?p.detailHtml:legacyDetailsToHtml(p.details||[])}
function openProduct(id){const p=id?S.data.products.find(x=>x.id===id):{id:uid(),name:'',group:'',w:'',d:'',h:'',weight_g:'',cbm:'',wood:'',finish:'',unitPrice:'',makers:[],parts:[],image:'',imageFileName:'',imageSource:'',details:[],detailHtml:''};window._pendingProductImage=p.image||'';window._pendingProductImageFileName=p.imageFileName||'';window._pendingProductImageSource=p.imageSource||'';window._editDetails=JSON.parse(JSON.stringify(p.details||[]));window._detailSelectedImage=null;modalBody.innerHTML=`<h2>${id?'Edit Produk':'Tambah Produk'}</h2><div class="form-grid"><div><div class="section-title">Gambar Produk</div>${p.image?`<img id="productImagePreview" class="upload-preview" src="${esc(p.image)}">`:`<img id="productImagePreview" class="upload-preview hidden"><div id="productNoImage" class="upload-preview noimg" style="display:flex;align-items:center;justify-content:center;color:#9ca3af">Tanpa Gambar</div>`}<div class="image-actions"><button class="secondary" onclick="chooseProductImage()">📷 Pilih dari Galeri</button><button class="secondary" onclick="takeProductPhoto()">📸 Ambil Foto</button><button class="secondary" onclick="window._pendingProductImage='';window._pendingProductImageFileName='';document.getElementById('productImagePreview').classList.add('hidden');document.getElementById('productNoImage')?.classList.remove('hidden');document.getElementById('productImageFileName').textContent=''">Hapus Gambar</button></div><div class="note">Nama file: <b id="productImageFileName">${esc(p.imageFileName||'')}</b></div></div><div><div class="field"><label>Nama Produk</label><input id="p_name" value="${esc(p.name)}"></div><div class="field" style="margin-top:10px"><label>Grup Produk</label><select id="p_group"><option value="">Pilih</option>${S.data.groups.map(g=>`<option value="${esc(g)}" ${p.group===g?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div class="section-title">Ukuran Produk (W × D × H)</div><div class="form-grid"><div class="field"><label>W (mm)</label><input id="p_w" type="number" value="${p.w||''}" oninput="calcProductCbm()"></div><div class="field"><label>D (mm)</label><input id="p_d" type="number" value="${p.d||''}" oninput="calcProductCbm()"></div><div class="field"><label>H (mm)</label><input id="p_h" type="number" value="${p.h||''}" oninput="calcProductCbm()"></div><div class="field"><label>Berat Produk (g)</label><input id="p_weight" type="number" value="${p.weight_g||''}"></div><div class="field"><label>CBM</label><input id="p_cbm" type="number" step="0.000001" value="${p.cbm||''}"></div><div class="field"><label>Harga Satuan Default</label><input id="p_unitprice" type="number" value="${p.unitPrice||''}"></div></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Jenis Kayu</label><input id="p_wood" value="${esc(p.wood)}"></div><div class="field"><label>Finishing</label><input id="p_finish" value="${esc(p.finish)}"></div></div></div><div class="span2"><div class="section-title">Komponen Tambahan</div><div id="parts"></div><button class="secondary" onclick="addPart()">+ Tambah Komponen</button></div><div class="span2"><div class="section-title">Produsen / Harga Produksi</div><div id="makers"></div><button class="secondary" onclick="addMaker()">+ Tambah Produsen</button></div><div class="span2"><div class="section-title">Detail Produk</div><div class="detail-note-shell"><div class="detail-note-top"><div><b>Catatan Detail Produk</b><div class="note">Samsung Notes처럼 한 장의 노트에 글과 이미지를 자연스럽게 정리합니다. 글을 쓸 위치를 누른 뒤 입력하고, 이미지는 현재 커서 위치에 들어갑니다.</div></div><button class="secondary no-print" type="button" onclick="addDetailEditorImage()">＋ Gambar</button></div><div class="detail-note-toolbar no-print"><button type="button" onclick="detailCommand('undo')" title="Undo">↶</button><button type="button" onclick="detailCommand('redo')" title="Redo">↷</button><span class="detail-tool-divider"></span><select onchange="detailFontSize(this.value);this.value=''" title="Ukuran teks"><option value="">Ukuran</option><option value="2">Kecil</option><option value="3">Normal</option><option value="4">Besar</option><option value="5">Judul</option></select><button type="button" onclick="detailCommand('bold')"><b>B</b></button><button type="button" onclick="detailCommand('underline')"><u>U</u></button><button type="button" onclick="detailCommand('insertUnorderedList')">• List</button><button type="button" onclick="detailCommand('insertOrderedList')">1. List</button><span class="detail-tool-divider"></span><button type="button" onclick="detailAlign('left')">왼쪽</button><button type="button" onclick="detailAlign('center')">가운데</button><button type="button" onclick="detailAlign('right')">오른쪽</button></div><div id="detailImageTools" class="detail-image-tools no-print hidden"><span>선택 이미지</span><button type="button" onclick="setSelectedDetailImageWidth(30)">작게</button><button type="button" onclick="setSelectedDetailImageWidth(50)">중간</button><button type="button" onclick="setSelectedDetailImageWidth(75)">크게</button><button type="button" onclick="setSelectedDetailImageWidth(100)">전체</button><span class="detail-tool-divider"></span><button type="button" onclick="detailImageAlign('left')">왼쪽</button><button type="button" onclick="detailImageAlign('center')">가운데</button><button type="button" onclick="detailImageAlign('right')">오른쪽</button><button class="danger" type="button" onclick="deleteSelectedDetailImage()">삭제</button></div><div class="detail-note-paper"><div id="detailEditor" class="detail-page-editor" contenteditable="true" spellcheck="false" data-placeholder="여기에 제품 상세내용을 입력하세요..." onmouseup="rememberDetailSelection()" onkeyup="rememberDetailSelection()" onfocus="rememberDetailSelection()">${detailEditorInitialHtml(p)}</div></div></div></div></div></div><div class="toolbar" style="margin-top:18px"><button class="primary" onclick="saveProduct('${p.id}',${!!id})">Simpan</button>${id?`<button class="secondary" onclick="printProduct('${p.id}')">PDF / Print</button><button class="danger" onclick="deleteRecord('products','${p.id}')">Hapus</button>`:''}</div>`;openModal();window._editParts=JSON.parse(JSON.stringify(p.parts||[]));window._editMakers=JSON.parse(JSON.stringify(p.makers||[]));drawParts();drawMakers();prepareDetailEditor()}
function calcProductCbm(){if(!window.p_cbm)return;const v=((+p_w.value||0)*(+p_d.value||0)*(+p_h.value||0))/1e9;p_cbm.value=v?v.toFixed(6):''}
function addPart(){_editParts.push({name:'',size:'',qty:1});drawParts()}
function drawParts(){parts.innerHTML=_editParts.map((x,i)=>`<div class="repeat-row parts-row"><div class="field"><label>Nama Komponen</label><input value="${esc(x.name)}" oninput="_editParts[${i}].name=this.value"></div><div class="field"><label>Ukuran</label><input value="${esc(x.size)}" placeholder="80x20x15" oninput="_editParts[${i}].size=this.value"></div><div class="field"><label>Jumlah</label><input type="number" min="1" value="${x.qty||1}" oninput="_editParts[${i}].qty=+this.value||1"></div><button class="danger" onclick="_editParts.splice(${i},1);drawParts()">Hapus</button></div>`).join('')||'<div class="note">Belum ada komponen tambahan.</div>'}
function addMaker(){_editMakers.push({workerId:'',price:''});drawMakers()}
function drawMakers(){makers.innerHTML=_editMakers.map((x,i)=>`<div class="repeat-row"><div class="field"><label>Produsen</label><select onchange="_editMakers[${i}].workerId=this.value"><option value="">Pilih</option>${S.data.workers.map(w=>`<option value="${w.id}" ${w.id===x.workerId?'selected':''}>${esc(w.name)}</option>`).join('')}</select></div><div class="field"><label>Harga Produksi</label><input type="number" value="${x.price||''}" oninput="_editMakers[${i}].price=+this.value||0"></div><button class="danger" onclick="_editMakers.splice(${i},1);drawMakers()">Hapus</button></div>`).join('')||'<div class="note">Pilih produsen dari DB Pekerja.</div>'}

function prepareDetailEditor(){const ed=document.getElementById('detailEditor');if(!ed)return;ed.querySelectorAll('img').forEach(img=>prepareDetailImage(img));ed.addEventListener('click',e=>{if(e.target===ed||!e.target.closest('img'))clearDetailImageSelection()});rememberDetailSelection()}
function prepareDetailImage(img){img.classList.add('detail-rich-img');img.setAttribute('contenteditable','false');img.draggable=false;img.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();selectDetailImage(img)})}
function rememberDetailSelection(){const ed=document.getElementById('detailEditor'),sel=window.getSelection();if(!ed||!sel||!sel.rangeCount)return;const r=sel.getRangeAt(0);if(ed.contains(r.commonAncestorContainer))window._detailSavedRange=r.cloneRange()}
function restoreDetailSelection(){const ed=document.getElementById('detailEditor'),sel=window.getSelection();if(!ed)return;ed.focus();sel.removeAllRanges();if(window._detailSavedRange&&ed.contains(window._detailSavedRange.commonAncestorContainer))sel.addRange(window._detailSavedRange);else{const r=document.createRange();r.selectNodeContents(ed);r.collapse(false);sel.addRange(r)}}
function detailCommand(cmd){restoreDetailSelection();document.execCommand(cmd,false,null);rememberDetailSelection()}
function detailFontSize(v){if(!v)return;restoreDetailSelection();document.execCommand('fontSize',false,v);rememberDetailSelection()}
function detailAlign(dir){restoreDetailSelection();document.execCommand(dir==='center'?'justifyCenter':dir==='right'?'justifyRight':'justifyLeft',false,null);rememberDetailSelection()}
function addDetailEditorImage(){rememberDetailSelection();const i=document.createElement('input');i.type='file';i.accept='image/*';i.onchange=async()=>{const f=i.files?.[0];if(!f)return;const src=await compressImageFile(f,1800,.88);restoreDetailSelection();const wrap=document.createElement('div');wrap.className='detail-image-line';wrap.style.textAlign='center';const img=document.createElement('img');img.src=src;img.className='detail-rich-img';img.style.width='60%';img.style.height='auto';img.dataset.fileName=f.name||mobileImageName('DETAIL');prepareDetailImage(img);wrap.appendChild(img);const sel=window.getSelection();if(sel.rangeCount){const r=sel.getRangeAt(0);r.deleteContents();r.insertNode(wrap);const p=document.createElement('p');p.innerHTML='<br>';wrap.after(p);r.setStart(p,0);r.collapse(true);sel.removeAllRanges();sel.addRange(r)}selectDetailImage(img);rememberDetailSelection()};i.click()}
function selectDetailImage(img){clearDetailImageSelection(false);window._detailSelectedImage=img;img.classList.add('detail-selected');document.getElementById('detailImageTools')?.classList.remove('hidden')}
function clearDetailImageSelection(hide=true){const old=window._detailSelectedImage;if(old)old.classList.remove('detail-selected');window._detailSelectedImage=null;if(hide)document.getElementById('detailImageTools')?.classList.add('hidden')}
function setSelectedDetailImageWidth(v){const img=window._detailSelectedImage;if(!img)return;img.style.width=`${v}%`;img.style.height='auto'}
function detailImageAlign(dir){const img=window._detailSelectedImage;if(!img)return;const line=img.closest('.detail-image-line')||img.parentElement;if(line)line.style.textAlign=dir==='center'?'center':dir==='right'?'right':'left'}
function resizeSelectedDetailImage(v){setSelectedDetailImageWidth(v)}
function deleteSelectedDetailImage(){const img=window._detailSelectedImage;if(!img)return;const line=img.closest('.detail-image-line');if(line)line.remove();else img.remove();clearDetailImageSelection();rememberDetailSelection()}
async function collectDetailHtml(productId){const ed=document.getElementById('detailEditor');if(!ed)return'';const clone=ed.cloneNode(true);clone.querySelectorAll('img').forEach(x=>{x.classList.remove('detail-selected');x.removeAttribute('draggable')});const imgs=[...clone.querySelectorAll('img')];for(let i=0;i<imgs.length;i++){const img=imgs[i],src=img.getAttribute('src')||'';if(src.startsWith('data:image/')){const uploaded=await uploadDataImage(src,`products/${productId}/details/rich-${Date.now()}-${i}.jpg`);img.setAttribute('src',uploaded)}}return clone.innerHTML}
async function saveProduct(id,exists){const detailHtml=await collectDetailHtml(id);const old=exists?S.data.products.find(x=>x.id===id):null;const p={id,name:p_name.value,group:p_group.value,w:+p_w.value||0,d:+p_d.value||0,h:+p_h.value||0,weight_g:+p_weight.value||0,cbm:+p_cbm.value||(((+p_w.value||0)*(+p_d.value||0)*(+p_h.value||0))/1e9),wood:p_wood.value,finish:p_finish.value,unitPrice:+p_unitprice.value||0,image:window._pendingProductImage||'',imageFileName:window._pendingProductImageFileName||'',imageSource:window._pendingProductImageSource||'',parts:_editParts,makers:_editMakers,details:old?.details||[],detailHtml};if(exists)S.data.products[S.data.products.findIndex(x=>x.id===id)]=p;else S.data.products.push(p);await persist('Produk disimpan');closeModal();render()}
function productPrintHtml(p){const detail=(p.detailHtml&&String(p.detailHtml).trim())?p.detailHtml:legacyDetailsToHtml(p.details||[]);return `<div class="product-print-page"><div class="product-print-head"><div class="product-print-image">${p.image?`<img src="${esc(p.image)}">`:'<div class="noimg">Tanpa Gambar</div>'}</div><div class="product-print-info"><h2>${esc(p.name||'')}</h2><div><b>Size</b> ${esc(productSize(p))} mm</div><div><b>Jenis Kayu</b> ${esc(p.wood||'')}</div><div><b>Finishing</b> ${esc(p.finish||'')}</div></div></div><div class="product-print-detail">${detail||'<div class="note">Belum ada detail produk.</div>'}</div></div>`}
function printProduct(id){const p=S.data.products.find(x=>x.id===id);if(!p)return;showPrint('',productPrintHtml(p))}
function printProducts(){if(!S.data.products.length)return alert('Tidak ada data untuk dicetak.');showPrint('',S.data.products.map(productPrintHtml).join(''))}
function renderBoxes(q=''){meta('DB Box','Nama box otomatis dari ukuran dalam W × D × H');const a=S.data.boxes.filter(x=>JSON.stringify(x).toLowerCase().includes(q)),allChecked=a.length&&a.every(x=>S.selectedBoxes.has(x.id));content.innerHTML=`<div class="toolbar"><label class="select-inline"><input type="checkbox" ${allChecked?'checked':''} onchange="setVisibleSelection('selectedBoxes',S.data.boxes.filter(x=>JSON.stringify(x).toLowerCase().includes((document.getElementById('searchBox').value||'').toLowerCase())),this.checked)"> Pilih semua</label><button class="secondary" onclick="clearSelection('selectedBoxes')">Batal Pilih</button><button class="danger" onclick="deleteSelectedBoxes()" ${S.selectedBoxes.size?'':'disabled'}>Hapus Pilihan (${S.selectedBoxes.size})</button><span class="spacer"></span><button class="secondary" onclick="exportExcel('boxes')">Excel</button><button class="secondary" onclick="printList('boxes')">PDF / Print</button><button class="primary" onclick="openBox()">+ Tambah Box</button></div><div class="table-wrap"><table><thead><tr><th></th><th>Nama Box</th><th>Harga</th><th>Stok Box</th><th>Berat Box</th><th>Workshop</th><th>Kontak</th><th>Produk yang Bisa Dipacking</th></tr></thead><tbody>${a.map(b=>`<tr><td onclick="event.stopPropagation()"><input type="checkbox" ${S.selectedBoxes.has(b.id)?'checked':''} onchange="toggleSelection('selectedBoxes','${b.id}',this.checked)"></td><td onclick="openBox('${b.id}')"><b>${b.w}x${b.d}x${b.h} Box</b></td><td onclick="openBox('${b.id}')">${money(b.price)}</td><td onclick="openBox('${b.id}')"><b>${fmt(b.qty)} pcs</b></td><td onclick="openBox('${b.id}')">${fmt(b.weight_g||0)} g</td><td onclick="openBox('${b.id}')">${esc(b.workplace)}</td><td onclick="openBox('${b.id}')">${esc(b.phone)}</td><td onclick="openBox('${b.id}')">${(b.productIds||[]).map(id=>`<span class="badge">${esc(prodName(id))}</span>`).join(' ')}</td></tr>`).join('')||'<tr><td colspan="8" class="note">Belum ada data box.</td></tr>'}</tbody></table></div>`}
function openBox(id){const b=id?S.data.boxes.find(x=>x.id===id):{id:uid(),w:'',d:'',h:'',price:'',qty:0,weight_g:0,workplace:'',phone:'',productIds:[]};modalBody.innerHTML=`<h2>${id?'Edit Box':'Tambah Box'}</h2><div class="form-grid"><div class="field"><label>W (dalam)</label><input id="b_w" type="number" value="${b.w||''}"></div><div class="field"><label>D (dalam)</label><input id="b_d" type="number" value="${b.d||''}"></div><div class="field"><label>H (dalam)</label><input id="b_h" type="number" value="${b.h||''}"></div><div class="field"><label>Harga Box</label><input id="b_price" type="number" value="${b.price||''}"></div><div class="field"><label>Jumlah / Stok Box</label><input id="b_qty" type="number" value="${b.qty||0}"></div><div class="field"><label>Berat Box Kosong (g)</label><input id="b_weight" type="number" min="0" value="${b.weight_g||0}"></div><div class="field"><label>Workshop</label><input id="b_workplace" value="${esc(b.workplace)}"></div><div class="field"><label>Kontak</label><input id="b_phone" value="${esc(b.phone)}"></div><div class="field span2"><label>Produk yang Bisa Dipacking</label><div class="gallery">${S.data.products.map(p=>`<label class="gallery-card mini-pick">${imgTag(p,'thumb')}<span><input type="checkbox" class="box-product" value="${p.id}" ${(b.productIds||[]).includes(p.id)?'checked':''}> ${esc(p.name)}</span></label>`).join('')}</div></div></div><div class="toolbar" style="margin-top:16px"><button class="primary" onclick="saveBox('${b.id}',${!!id})">Simpan</button>${id?`<button class="danger" onclick="deleteRecord('boxes','${b.id}')">Hapus</button>`:''}</div>`;openModal()}
async function saveBox(id,exists){const b={id,w:+b_w.value||0,d:+b_d.value||0,h:+b_h.value||0,price:+b_price.value||0,qty:+b_qty.value||0,weight_g:+b_weight.value||0,workplace:b_workplace.value,phone:b_phone.value,productIds:[...document.querySelectorAll('.box-product:checked')].map(x=>x.value)};if(exists)S.data.boxes[S.data.boxes.findIndex(x=>x.id===id)]=b;else S.data.boxes.push(b);await persist('Box disimpan');closeModal();render()}
function orderTotal(o){return orderRows(o).reduce((s,r)=>s+(+r.unitPrice||0)*(+r.qty||0),0)}
function renderOrders(q=''){meta('Order','Daftar ini menunjukkan sisa produksi yang belum selesai');const a=S.data.orders.filter(o=>!o.archived&&o.items?.length&&JSON.stringify(o).toLowerCase().includes(q)),allChecked=a.length&&a.every(x=>S.selectedOrders.has(x.id));content.innerHTML=`<div class="toolbar"><label class="select-inline"><input type="checkbox" ${allChecked?'checked':''} onchange="setVisibleSelection('selectedOrders',S.data.orders.filter(o=>!o.archived&&o.items?.length&&JSON.stringify(o).toLowerCase().includes((document.getElementById('searchBox').value||'').toLowerCase())),this.checked)"> Pilih semua</label><button class="secondary" onclick="clearSelection('selectedOrders')">Batal Pilih</button><button class="danger" onclick="deleteSelectedOrders()" ${S.selectedOrders.size?'':'disabled'}>Hapus Pilihan (${S.selectedOrders.size})</button><span class="spacer"></span><button class="primary" onclick="openOrder()">+ Buat Order</button></div><div class="table-wrap"><table><thead><tr><th></th><th>No. Order</th><th>Pekerja</th><th>Jenis Produk</th><th>Total Pcs Tersisa</th><th>Total Nilai</th><th>Tanggal Dibuat</th><th></th></tr></thead><tbody>${a.map(o=>`<tr><td onclick="event.stopPropagation()"><input type="checkbox" ${S.selectedOrders.has(o.id)?'checked':''} onchange="toggleSelection('selectedOrders','${o.id}',this.checked)"></td><td onclick="openOrder('${o.id}')"><b>${esc(o.orderNo)}</b></td><td onclick="openOrder('${o.id}')">${esc(workerName(o.workerId))}</td><td onclick="openOrder('${o.id}')">${o.items.length}</td><td onclick="openOrder('${o.id}')">${fmt(o.items.reduce((s,i)=>s+(+i.qty||0),0))}</td><td onclick="openOrder('${o.id}')"><b>${money(orderTotal(o))}</b></td><td onclick="openOrder('${o.id}')">${new Date(o.createdAt).toLocaleDateString('id-ID')}</td><td><button class="secondary" onclick="openOrder('${o.id}')">Buka</button></td></tr>`).join('')||'<tr><td colspan="8" class="note">Tidak ada order aktif. Semua produk yang selesai akan hilang otomatis dari sini.</td></tr>'}</tbody></table></div>`}
function openOrder(id){const o=id?S.data.orders.find(x=>x.id===id):{id:uid(),orderNo:todayCode(),createdAt:new Date().toISOString(),workerId:'',items:[],note:'',archived:false};window._order=JSON.parse(JSON.stringify(o));modalBody.innerHTML=`<h2>Order</h2><div class="form-grid"><div class="field"><label>No. Order</label><input id="o_no" value="${esc(o.orderNo)}"></div><div class="field"><label>Pekerja</label><select id="o_worker" onchange="drawOrderItems()"><option value="">Pilih</option>${S.data.workers.map(w=>`<option value="${w.id}" ${o.workerId===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select></div><div class="field span2"><label>Catatan Order</label><textarea id="o_note">${esc(o.note)}</textarea></div><div class="span2"><div class="section-title">Daftar Produk Order / Sisa Produksi</div><div id="orderItems"></div><button class="secondary" onclick="addOrderItem()">+ Tambah Produk</button><div id="orderGrandTotal" class="order-grand-total"></div></div></div><div class="toolbar" style="margin-top:16px"><button class="primary" onclick="saveOrder('${o.id}',${!!id})">Simpan</button>${id?`<button class="secondary" onclick="exportOrderExcel('${o.id}')">Excel</button><button class="secondary" onclick="printOrder('${o.id}')">PDF / Print</button><button class="danger" onclick="archiveOrder('${o.id}')">Hapus dari Daftar Order</button>`:''}</div>`;openModal();drawOrderItems()}
function addOrderItem(){_order.items.push({productId:'',qty:1,note:''});drawOrderItems()}
function drawOrderItems(){if(!window.orderItems)return;const wid=document.getElementById('o_worker')?.value||_order.workerId;let total=0;orderItems.innerHTML=_order.items.map((x,i)=>{const p=S.data.products.find(p=>p.id===x.productId);const price=priceForWorker(p,wid),amount=price*(+x.qty||0);total+=amount;return `<div class="order-line"><div class="field"><label>Produk</label><select onchange="_order.items[${i}].productId=this.value;drawOrderItems()"><option value="">Pilih</option>${S.data.products.map(p=>`<option value="${p.id}" ${p.id===x.productId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Harga Satuan</label><input id="order_price_${i}" value="${price?money(price):'-'}" readonly></div><div class="field"><label>Jumlah</label><input type="number" min="0" value="${x.qty}" oninput="_order.items[${i}].qty=+this.value||0;updateOrderTotals()"></div><div class="field"><label>Jumlah Harga</label><input id="order_amount_${i}" value="${money(amount)}" readonly></div><div class="field"><label>Catatan</label><input value="${esc(x.note||'')}" oninput="_order.items[${i}].note=this.value"></div><button class="danger" onclick="_order.items.splice(${i},1);drawOrderItems()">Hapus</button></div>`}).join('');orderGrandTotal.innerHTML=`<b>Total Keseluruhan Order</b><strong>${money(total)}</strong>`}
function updateOrderTotals(){if(!window._order)return;const wid=document.getElementById('o_worker')?.value||_order.workerId;let total=0;_order.items.forEach((x,i)=>{const p=S.data.products.find(p=>p.id===x.productId),price=priceForWorker(p,wid),amount=price*(+x.qty||0);total+=amount;const pe=document.getElementById(`order_price_${i}`),ae=document.getElementById(`order_amount_${i}`);if(pe)pe.value=price?money(price):'-';if(ae)ae.value=money(amount)});if(window.orderGrandTotal)orderGrandTotal.innerHTML=`<b>Total Keseluruhan Order</b><strong>${money(total)}</strong>`}
async function saveOrder(id,exists){_order.orderNo=o_no.value||todayCode();_order.workerId=o_worker.value;_order.note=o_note.value;_order.items=_order.items.filter(i=>i.productId&&(+i.qty||0)>0);if(exists)S.data.orders[S.data.orders.findIndex(x=>x.id===id)]=_order;else S.data.orders.push(_order);await persist('Order disimpan / sisa produksi diperbarui');closeModal();render()}
async function archiveOrder(id){const o=S.data.orders.find(x=>x.id===id);o.archived=true;await persist('Order dihapus dari daftar aktif');closeModal();render()}
function orderRows(o){return (o.items||[]).map(i=>{const p=S.data.products.find(x=>x.id===i.productId)||{};return{p,image:p.image||'',name:p.name||'',size:productSize(p),wood:p.wood||'',finish:p.finish||'',unitPrice:priceForWorker(p,o.workerId),qty:+i.qty||0,note:i.note||''}})}
function printOrder(id){const o=S.data.orders.find(x=>x.id===id);const rr=orderRows(o),total=rr.reduce((s,r)=>s+r.unitPrice*r.qty,0);const rows=rr.map(r=>`<tr><td>${imgTag(r.p,'invoice-img')}</td><td><b>${esc(r.name)}</b></td><td>${esc(r.size)}</td><td>${esc(r.wood)}</td><td>${esc(r.finish)}</td><td>${money(r.unitPrice)}</td><td>${fmt(r.qty)}</td><td>${esc(r.note)}</td></tr>`).join('');showPrint(`ORDER / ${esc(o.orderNo)}`,`<div class="invoice-meta"><div><b>No. Order</b> ${esc(o.orderNo)}</div><div><b>Pekerja</b> ${esc(workerName(o.workerId))}</div><div><b>Tanggal</b> ${new Date(o.createdAt).toLocaleDateString('id-ID')}</div><div><b>Catatan</b> ${esc(o.note)}</div></div><table><thead><tr><th>Gambar</th><th>Nama Produk</th><th>Ukuran</th><th>Jenis Kayu</th><th>Finishing</th><th>Harga Satuan</th><th>Jumlah</th><th>Catatan</th></tr></thead><tbody>${rows}</tbody><tfoot><tr><th colspan="6" style="text-align:right">TOTAL KESELURUHAN</th><th colspan="2">${money(total)}</th></tr></tfoot></table>`)}
async function exportOrderExcel(id){const o=S.data.orders.find(x=>x.id===id);if(!o)return;const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet('Order');ws.mergeCells('A1:H1');ws.getCell('A1').value=`NAYESO INDONESIA / ORDER ${o.orderNo}`;ws.getCell('A1').font={bold:true,size:16};ws.getCell('A1').alignment={horizontal:'center'};ws.mergeCells('A2:B2');ws.getCell('A2').value=`Pekerja: ${workerName(o.workerId)}`;ws.mergeCells('C2:D2');ws.getCell('C2').value=`Tanggal: ${new Date(o.createdAt).toLocaleDateString('id-ID')}`;ws.mergeCells('E2:H2');ws.getCell('E2').value=`Catatan: ${o.note||''}`;const headers=['Gambar','Nama Produk','Ukuran','Jenis Kayu','Finishing','Harga Satuan','Jumlah','Catatan'];ws.addRow([]);ws.addRow(headers);const hr=ws.getRow(4);hr.font={bold:true,color:{argb:'FFFFFFFF'}};hr.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF17212E'}};hr.alignment={horizontal:'center',vertical:'middle'};hr.height=24;ws.columns=[{width:14},{width:28},{width:17},{width:18},{width:18},{width:16},{width:10},{width:28}];const rows=orderRows(o);for(let idx=0;idx<rows.length;idx++){const r=rows[idx],rowNo=5+idx;ws.addRow(['',r.name,r.size,r.wood,r.finish,r.unitPrice,r.qty,r.note]);const row=ws.getRow(rowNo);row.height=62;row.getCell(6).numFmt='Rp #,##0';row.alignment={vertical:'middle',wrapText:true};if(r.image)try{const img=await fetchImageForExcel(r.image);if(img){const imageId=wb.addImage(img);ws.addImage(imageId,{tl:{col:0.15,row:rowNo-0.85},ext:{width:72,height:58},editAs:'oneCell'})}}catch(e){console.warn('Gambar Excel dilewati',e)}}const totalRow=5+rows.length;ws.mergeCells(`A${totalRow}:F${totalRow}`);ws.getCell(`A${totalRow}`).value='TOTAL KESELURUHAN';ws.getCell(`A${totalRow}`).font={bold:true};ws.getCell(`A${totalRow}`).alignment={horizontal:'right'};ws.mergeCells(`G${totalRow}:H${totalRow}`);ws.getCell(`G${totalRow}`).value=orderTotal(o);ws.getCell(`G${totalRow}`).numFmt='Rp #,##0';ws.getCell(`G${totalRow}`).font={bold:true};for(let r=4;r<=totalRow;r++)for(let c=1;c<=8;c++)ws.getCell(r,c).border={top:{style:'thin'},left:{style:'thin'},bottom:{style:'thin'},right:{style:'thin'}};const buf=await wb.xlsx.writeBuffer();downloadBlob(new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),`NAYESO_Order_${o.orderNo}.xlsx`)}
async function fetchImageForExcel(src){if(src.startsWith('data:')){const [meta,b64]=src.split(',');return{base64:b64,extension:meta.includes('png')?'png':'jpeg'}}const res=await fetch(src,{mode:'cors'});if(!res.ok)return null;const blob=await res.blob(),buf=await blob.arrayBuffer();return{buffer:buf,extension:blob.type.includes('png')?'png':'jpeg'}}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function completedMetrics(c){const p=S.data.products.find(x=>x.id===c.productId)||{};const weightG=(+p.weight_g||0)*(+c.totalQty||0),cbm=(+p.cbm||0)*(+c.totalQty||0);return{weightG,weightKg:weightG/1000,cbm}}
function boxName(id){const b=S.data.boxes.find(x=>x.id===id);return b?`${b.w}x${b.d}x${b.h} Box`:''}
function toggleCompleted(id,checked){checked?S.selectedCompleted.add(id):S.selectedCompleted.delete(id);render()}
function toggleAllCompleted(checked){const q=(document.getElementById('searchBox').value||'').toLowerCase();S.data.completed.filter(x=>JSON.stringify(x).toLowerCase().includes(q)).forEach(x=>checked?S.selectedCompleted.add(x.id):S.selectedCompleted.delete(x.id));render()}
function renderCompleted(q=''){meta('Produk Selesai','Selesai packing → box otomatis berkurang · setelah dikirim dapat dipindahkan ke riwayat pengiriman');const a=S.data.completed.filter(x=>JSON.stringify(x).toLowerCase().includes(q)),allChecked=a.length&&a.every(x=>S.selectedCompleted.has(x.id));const shipped=S.data.shipments.slice().sort((a,b)=>String(b.shippedAt).localeCompare(String(a.shippedAt)));content.innerHTML=`<div class="toolbar"><label class="select-inline"><input type="checkbox" ${allChecked?'checked':''} onchange="toggleAllCompleted(this.checked)"> Pilih semua</label><button class="primary" onclick="shipSelectedCompleted()" ${S.selectedCompleted.size?'':'disabled'}>Tandai Sudah Dikirim (${S.selectedCompleted.size})</button><button class="danger" onclick="deleteSelectedCompleted()" ${S.selectedCompleted.size?'':'disabled'}>Hapus Pilihan (${S.selectedCompleted.size})</button><span class="spacer"></span><button class="secondary" onclick="exportExcel('completed')">Excel</button><button class="secondary" onclick="printList('completed')">PDF / Print</button><button class="primary" onclick="openCompleted()">+ Tambah Produk Selesai</button></div><div class="table-wrap"><table><thead><tr><th></th><th>Produk</th><th>Grup</th><th>No.</th><th>Box Digunakan</th><th>Isi / Box</th><th>Jumlah Box</th><th>Total Packing</th><th>Berat Produk Total (Net)</th><th>Total CBM</th><th>Tanggal Selesai</th></tr></thead><tbody>${a.map(c=>{const m=completedMetrics(c);return `<tr><td onclick="event.stopPropagation()"><input type="checkbox" ${S.selectedCompleted.has(c.id)?'checked':''} onchange="toggleCompleted('${c.id}',this.checked)"></td><td onclick="openCompleted('${c.id}')">${esc(prodName(c.productId))}</td><td onclick="openCompleted('${c.id}')">${esc(c.group)}</td><td onclick="openCompleted('${c.id}')">${esc(c.seq)}</td><td onclick="openCompleted('${c.id}')">${esc(boxName(c.boxId)||'-')}</td><td onclick="openCompleted('${c.id}')">${fmt(c.perBox)}</td><td onclick="openCompleted('${c.id}')">${fmt(c.boxCount)}</td><td onclick="openCompleted('${c.id}')"><b>${fmt(c.totalQty)}</b></td><td onclick="openCompleted('${c.id}')">${m.weightKg.toFixed(2)} kg</td><td onclick="openCompleted('${c.id}')">${m.cbm.toFixed(6)}</td><td onclick="openCompleted('${c.id}')">${new Date(c.completedAt).toLocaleDateString('id-ID')}</td></tr>`}).join('')||'<tr><td colspan="11" class="note">Tidak ada produk selesai yang menunggu pengiriman.</td></tr>'}</tbody></table></div><div class="section-title">Riwayat Pengiriman / Product List</div><div class="table-wrap"><table><thead><tr><th>Tanggal Pengiriman</th><th>Jumlah Jenis</th><th>Total Qty</th><th></th></tr></thead><tbody>${shipped.map(sh=>`<tr onclick="openShipmentEditor('${sh.id}')"><td><b>${esc(sh.shipCode)}</b></td><td>${sh.items.length}</td><td>${fmt(sh.items.reduce((n,x)=>n+(+x.totalQty||0),0))} pcs</td><td onclick="event.stopPropagation()"><button class="secondary" onclick="openShipmentEditor('${sh.id}')">Ubah / Batalkan</button> <button class="secondary" onclick="printShipment('${sh.id}')">PDF / Print</button> <button class="secondary" onclick="exportShipmentExcel('${sh.id}')">Excel</button></td></tr>`).join('')||'<tr><td colspan="4" class="note">Belum ada riwayat pengiriman.</td></tr>'}</tbody></table></div>`}
function activeOrdersForCompletion(){return S.data.orders.filter(o=>!o.archived&&(o.items||[]).some(i=>i.productId&&(+i.qty||0)>0))}
function openCompleted(id){let c=id?S.data.completed.find(x=>x.id===id):{id:uid(),orderId:'',productId:'',group:'',seq:'',boxId:'',orderQty:0,perBox:0,boxCount:0,totalQty:0,note:'',completedAt:new Date().toISOString()};const orders=activeOrdersForCompletion();modalBody.innerHTML=`<h2>Produk Selesai</h2><div class="form-grid"><div class="field"><label>Order Aktif</label><select id="c_order" onchange="fillCompletedProducts()" ${id?'disabled':''}><option value="">Pilih</option>${orders.map(o=>`<option value="${o.id}" ${c.orderId===o.id?'selected':''}>${esc(o.orderNo)} / ${esc(workerName(o.workerId))}</option>`).join('')}${id&&!orders.some(o=>o.id===c.orderId)?`<option value="${c.orderId}" selected>Order selesai / arsip</option>`:''}</select></div><div class="field"><label>Produk</label><select id="c_product" ${id?'disabled':''}></select></div><div class="field"><label>Grup</label><select id="c_group"><option value="">Pilih</option>${S.data.groups.map(g=>`<option value="${esc(g)}" ${c.group===g?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div class="field"><label>No. Urut (manual)</label><input id="c_seq" value="${esc(c.seq)}"></div><div class="field span2"><label>Box Digunakan</label><select id="c_box"><option value="">Pilih Box</option>${S.data.boxes.map(b=>`<option value="${b.id}" ${c.boxId===b.id?'selected':''}>${b.w}x${b.d}x${b.h} Box · stok ${fmt(b.qty)}</option>`).join('')}</select></div><div class="field"><label>Jumlah Order / Sisa Saat Dipilih</label><input id="c_orderqty" type="number" value="${c.orderQty||0}" readonly></div><div class="field"><label>Isi per Box</label><input id="c_perbox" type="number" value="${c.perBox||0}" oninput="calcComplete()"></div><div class="field"><label>Jumlah Box</label><input id="c_boxcount" type="number" value="${c.boxCount||0}" oninput="calcComplete()"></div><div class="field"><label>Total Packing</label><input id="c_total" value="${c.totalQty||0}" readonly></div><div class="field span2"><label>Selisih Jumlah</label><div id="c_diff" class="note"></div></div><div class="field span2"><label>Berat Produk (Net) / CBM</label><div id="c_ship" class="note"></div></div><div class="field span2"><label>Catatan</label><textarea id="c_note">${esc(c.note)}</textarea></div></div><div class="toolbar" style="margin-top:16px"><button class="primary" onclick="saveCompleted('${c.id}',${!!id})">Simpan</button>${id?`<button class="danger" onclick="deleteCompleted('${c.id}')">Hapus & Kembalikan ke Order</button>`:''}</div>`;openModal();window._completeOriginal=JSON.parse(JSON.stringify(c));fillCompletedProducts(c.productId);calcComplete()}
function applyCompletedProductDefaults(){const p=S.data.products.find(x=>x.id===c_product.value);if(p&&window.c_group)c_group.value=p.group||''}
function fillCompletedProducts(selected=''){const o=S.data.orders.find(x=>x.id===c_order.value);if(o){const opts=o.items.filter(i=>(+i.qty||0)>0).map(i=>`<option value="${i.productId}" ${selected===i.productId?'selected':''}>${esc(prodName(i.productId))} / sisa ${fmt(i.qty)}</option>`);if(selected&&!o.items.some(i=>i.productId===selected))opts.unshift(`<option value="${selected}" selected>${esc(prodName(selected))} / riwayat selesai</option>`);c_product.innerHTML=`<option value="">Pilih</option>`+opts.join('')}else if(selected||window._completeOriginal?.productId){const pid=selected||window._completeOriginal.productId;c_product.innerHTML=`<option value="${pid}" selected>${esc(prodName(pid))}</option>`}else c_product.innerHTML='<option value="">Pilih</option>';c_product.onchange=()=>{const oo=S.data.orders.find(x=>x.id===c_order.value),item=oo?.items.find(i=>i.productId===c_product.value);c_orderqty.value=item?.qty||0;applyCompletedProductDefaults();calcComplete()};const item=o?.items.find(i=>i.productId===selected);if(item)c_orderqty.value=item.qty;else if(window._completeOriginal?.productId===selected)c_orderqty.value=window._completeOriginal.orderQty||0;if(!window._completeOriginal?.group&&selected)applyCompletedProductDefaults()}
function calcComplete(){if(!window.c_total)return;const total=(+c_perbox.value||0)*(+c_boxcount.value||0),diff=total-(+c_orderqty.value||0);c_total.value=total;c_diff.innerHTML=diff===0?`<span class="ok">Sama dengan jumlah order.</span>`:`<span class="${diff>0?'warn':'negative'}">Selisih ${diff>0?'+':''}${diff} pcs dari order.</span>`;const p=S.data.products.find(x=>x.id===c_product.value)||{},wg=(+p.weight_g||0)*total,cbm=(+p.cbm||0)*total;c_ship.innerHTML=`Berat produk total (Net): <b>${(wg/1000).toFixed(2)} kg</b> (${fmt(wg)} g) · Total CBM: <b>${cbm.toFixed(6)}</b>`}
function restoreCompletionToOrder(c){if(!c?.orderId||!c?.productId)return;let o=S.data.orders.find(x=>x.id===c.orderId);if(!o)return;const restoreQty=c.consumedQty===undefined||c.consumedQty===null?Math.min(+c.totalQty||0,+c.orderQty||(+c.totalQty||0)):(+c.consumedQty||0);if(restoreQty<=0)return;o.archived=false;let item=o.items.find(i=>i.productId===c.productId);if(item)item.qty=(+item.qty||0)+restoreQty;else o.items.push({productId:c.productId,qty:restoreQty,note:''})}
function restoreBoxStock(c){if(!c?.boxId||!(+c.boxCount||0))return;const b=S.data.boxes.find(x=>x.id===c.boxId);if(b)b.qty=(+b.qty||0)+(+c.boxCount||0)}
function consumeBoxStock(boxId,count){if(!boxId||!(+count||0))return;const b=S.data.boxes.find(x=>x.id===boxId);if(b)b.qty=(+b.qty||0)-(+count||0)}
function consumeOrderQty(order,productId,qty){if(!order)return 0;const item=order.items.find(i=>i.productId===productId);if(!item)return 0;const consume=Math.min(+qty||0,+item.qty||0);item.qty=(+item.qty||0)-consume;if(item.qty<=0)order.items=order.items.filter(i=>i!==item);if(!order.items.length)order.archived=true;return consume}
async function saveCompleted(id,exists){const old=exists?S.data.completed.find(x=>x.id===id):null;if(exists&&old){restoreCompletionToOrder(old);restoreBoxStock(old)}const order=S.data.orders.find(x=>x.id===c_order.value),product=S.data.products.find(x=>x.id===c_product.value)||{},total=+c_total.value||0,consumed=consumeOrderQty(order,c_product.value,total),unitPrice=priceForWorker(product,order?.workerId||old?.workerId),boxId=c_box.value,boxCount=+c_boxcount.value||0;consumeBoxStock(boxId,boxCount);const c={id,orderId:c_order.value,workerId:order?.workerId||old?.workerId||'',productId:c_product.value,group:c_group.value,seq:c_seq.value,boxId,orderQty:+c_orderqty.value||0,perBox:+c_perbox.value||0,boxCount,totalQty:total,consumedQty:consumed,unitPrice,amount:unitPrice*total,totalWeightG:(+product.weight_g||0)*total,totalCbm:(+product.cbm||0)*total,note:c_note.value,completedAt:exists?(old?.completedAt||new Date().toISOString()):new Date().toISOString(),orderNo:order?.orderNo||old?.orderNo||''};if(exists)S.data.completed[S.data.completed.findIndex(x=>x.id===id)]=c;else S.data.completed.push(c);await persist('Produk selesai disimpan · Order & stok Box otomatis diperbarui');closeModal();render()}
async function deleteCompleted(id){const c=S.data.completed.find(x=>x.id===id);if(!c)return;if(!confirm('Hapus riwayat selesai ini? Qty akan kembali ke Order dan stok Box akan dikembalikan.'))return;restoreCompletionToOrder(c);restoreBoxStock(c);S.data.completed=S.data.completed.filter(x=>x.id!==id);S.selectedCompleted.delete(id);await persist('Produk selesai dihapus · qty Order & stok Box dikembalikan');closeModal();render()}
function shipmentSnapshot(c){const p=S.data.products.find(x=>x.id===c.productId)||{};return{id:c.id,orderId:c.orderId,orderNo:c.orderNo,workerId:c.workerId,productId:c.productId,productName:p.name||prodName(c.productId),image:p.image||'',size:productSize(p),group:c.group||'',seq:c.seq||'',totalQty:+c.totalQty||0,consumedQty:c.consumedQty===undefined?Math.min(+c.totalQty||0,+c.orderQty||(+c.totalQty||0)):(+c.consumedQty||0),orderQty:+c.orderQty||0,perBox:+c.perBox||0,boxCount:+c.boxCount||0,boxId:c.boxId||'',note:c.note||'',completedAt:c.completedAt,unitPrice:+c.unitPrice||0,amount:+c.amount||0}}
function shipSelectedCompleted(){const ids=[...S.selectedCompleted].filter(id=>S.data.completed.some(c=>c.id===id));if(!ids.length)return alert('Pilih produk yang sudah dikirim.');const d=new Date(),date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;modalBody.innerHTML=`<h2>Tandai Sudah Dikirim</h2><p class="note">Produk yang dipilih akan hilang dari daftar Produk Selesai dan disimpan sebagai Product List.</p><div class="field"><label>Tanggal Pengiriman</label><input id="ship_date" type="date" value="${date}"></div><div class="toolbar" style="margin-top:16px"><button class="primary" onclick="confirmShipment()">Simpan Pengiriman</button><button class="secondary" onclick="closeModal()">Batal</button></div>`;openModal()}
async function confirmShipment(){const ids=[...S.selectedCompleted].filter(id=>S.data.completed.some(c=>c.id===id));if(!ids.length)return;const val=ship_date.value||new Date().toISOString().slice(0,10),dt=new Date(val+'T12:00:00'),code=String(dt.getFullYear()).slice(2)+String(dt.getMonth()+1).padStart(2,'0')+String(dt.getDate()).padStart(2,'0'),items=S.data.completed.filter(c=>ids.includes(c.id)).map(shipmentSnapshot),sh={id:uid(),shipCode:code,shippedAt:dt.toISOString(),items};S.data.shipments.push(sh);S.data.completed=S.data.completed.filter(c=>!ids.includes(c.id));S.selectedCompleted.clear();await persist(`Pengiriman ${code} · Product List dibuat`);closeModal();render();}
function shipmentById(id){return S.data.shipments.find(x=>x.id===id)}
function openShipmentEditor(id){const sh=shipmentById(id);if(!sh)return;const date=(sh.shippedAt||new Date().toISOString()).slice(0,10);modalBody.innerHTML=`<h2>Ubah / Batalkan Pengiriman</h2><p class="note">Tanggal pengiriman dapat diubah. Centang produk yang perlu diperbaiki lalu kembalikan ke Produk Selesai. Setelah dikembalikan, produk dapat diedit dan dikirim ulang.</p><div class="form-grid"><div class="field"><label>Tanggal Pengiriman</label><input id="edit_ship_date" type="date" value="${date}"></div></div><div class="section-title">Produk dalam Product List</div><div class="table-wrap"><table><thead><tr><th></th><th>Produk</th><th>Grup / No.</th><th>Total Qty</th><th>Isi / Box</th><th>Jumlah Box</th></tr></thead><tbody>${sh.items.map(x=>`<tr><td><input class="ship-return-check" type="checkbox" value="${x.id}"></td><td>${esc(x.productName)}</td><td>${esc(x.group)} ${esc(x.seq)}</td><td>${fmt(x.totalQty)}</td><td>${fmt(x.perBox)}</td><td>${fmt(x.boxCount)}</td></tr>`).join('')}</tbody></table></div><div class="toolbar" style="margin-top:16px"><button class="primary" onclick="saveShipmentEdit('${sh.id}')">Simpan Tanggal</button><button class="secondary" onclick="returnShipmentItems('${sh.id}')">Batalkan Produk Terpilih</button><button class="danger" onclick="cancelWholeShipment('${sh.id}')">Batalkan Seluruh Pengiriman</button><button class="secondary" onclick="closeModal()">Tutup</button></div>`;openModal()}
async function saveShipmentEdit(id){const sh=shipmentById(id);if(!sh)return;const val=document.getElementById('edit_ship_date')?.value;if(!val)return alert('Pilih tanggal pengiriman.');const dt=new Date(val+'T12:00:00');sh.shippedAt=dt.toISOString();sh.shipCode=String(dt.getFullYear()).slice(2)+String(dt.getMonth()+1).padStart(2,'0')+String(dt.getDate()).padStart(2,'0');await persist(`Tanggal pengiriman ${sh.shipCode} diperbarui`);closeModal();render()}
function shipmentItemToCompleted(x){const total=+x.totalQty||0,orderQty=+x.orderQty||total,consumed=x.consumedQty===undefined||x.consumedQty===null?Math.min(total,orderQty):(+x.consumedQty||0);return{id:x.id||uid(),orderId:x.orderId||'',orderNo:x.orderNo||'',workerId:x.workerId||'',productId:x.productId||'',group:x.group||'',seq:x.seq||'',boxId:x.boxId||'',orderQty,perBox:+x.perBox||0,boxCount:+x.boxCount||0,totalQty:total,consumedQty:consumed,note:x.note||'',completedAt:x.completedAt||new Date().toISOString(),unitPrice:+x.unitPrice||0,amount:+x.amount||0}}
async function returnShipmentItems(id){const sh=shipmentById(id);if(!sh)return;const ids=[...document.querySelectorAll('.ship-return-check:checked')].map(el=>el.value);if(!ids.length)return alert('Pilih produk yang ingin dibatalkan dari pengiriman.');const back=sh.items.filter(x=>ids.includes(String(x.id)));for(const x of back){if(!S.data.completed.some(c=>c.id===x.id))S.data.completed.push(shipmentItemToCompleted(x))}sh.items=sh.items.filter(x=>!ids.includes(String(x.id)));if(!sh.items.length)S.data.shipments=S.data.shipments.filter(x=>x.id!==id);await persist('Produk pengiriman dikembalikan ke Produk Selesai');closeModal();render()}
async function cancelWholeShipment(id){const sh=shipmentById(id);if(!sh)return;if(!confirm('Batalkan seluruh pengiriman ini dan kembalikan semua produk ke Produk Selesai?'))return;for(const x of sh.items){if(!S.data.completed.some(c=>c.id===x.id))S.data.completed.push(shipmentItemToCompleted(x))}S.data.shipments=S.data.shipments.filter(x=>x.id!==id);await persist('Seluruh pengiriman dibatalkan');closeModal();render()}
function printShipment(id){const sh=shipmentById(id);if(!sh)return;const rows=sh.items.map(x=>`<tr><td>${x.image?`<img class="invoice-img" src="${esc(x.image)}">`:'-'}</td><td><b>${esc(x.productName)}</b></td><td>${esc(x.size)}</td><td>${esc(x.group)}</td><td>${esc(x.seq)}</td><td>${fmt(x.totalQty)}</td><td>${fmt(x.perBox)}</td><td>${fmt(x.boxCount)}</td><td>${esc(x.note)}</td></tr>`).join('');showPrint('Product List',`<div class="invoice-meta"><div><b>${esc(sh.shipCode)}</b></div></div><table><thead><tr><th>Gambar</th><th>Nama Produk</th><th>Ukuran</th><th>Grup</th><th>No.</th><th>Total Qty</th><th>Isi / Box</th><th>Jumlah Box</th><th>Catatan</th></tr></thead><tbody>${rows}</tbody></table>`)}
async function exportShipmentExcel(id){const sh=shipmentById(id);if(!sh)return;const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet('Product List');ws.mergeCells('A1:I1');ws.getCell('A1').value='Product List';ws.getCell('A1').font={bold:true,size:18};ws.getCell('A1').alignment={horizontal:'center'};ws.mergeCells('A2:I2');ws.getCell('A2').value=sh.shipCode;ws.getCell('A2').font={bold:true};ws.getCell('A2').alignment={horizontal:'left'};const headers=['Gambar','Nama Produk','Ukuran','Grup','No.','Total Qty','Isi / Box','Jumlah Box','Catatan'];ws.addRow(headers);const hr=ws.getRow(3);hr.font={bold:true,color:{argb:'FFFFFFFF'}};hr.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF17212E'}};hr.alignment={horizontal:'center',vertical:'middle'};ws.columns=[{width:14},{width:28},{width:18},{width:16},{width:10},{width:12},{width:12},{width:12},{width:30}];for(let i=0;i<sh.items.length;i++){const x=sh.items[i],rowNo=4+i;ws.addRow(['',x.productName,x.size,x.group,x.seq,x.totalQty,x.perBox,x.boxCount,x.note]);const row=ws.getRow(rowNo);row.height=62;row.alignment={vertical:'middle',wrapText:true};if(x.image)try{const img=await fetchImageForExcel(x.image);if(img){const imageId=wb.addImage(img);ws.addImage(imageId,{tl:{col:.15,row:rowNo-.85},ext:{width:72,height:58},editAs:'oneCell'})}}catch(e){console.warn(e)}}for(let r=3;r<=3+sh.items.length;r++)for(let c=1;c<=9;c++)ws.getCell(r,c).border={top:{style:'thin'},left:{style:'thin'},bottom:{style:'thin'},right:{style:'thin'}};const buf=await wb.xlsx.writeBuffer();downloadBlob(new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),`Product_List_${sh.shipCode}.xlsx`)}
function renderInventory(q=''){meta('Stok Produk','Nama · Jenis Kayu · Finishing · Jumlah · Lokasi');const a=S.data.inventory.filter(x=>JSON.stringify(x).toLowerCase().includes(q)),allChecked=a.length&&a.every(x=>S.selectedInventory.has(x.id));content.innerHTML=`<div class="toolbar"><label class="select-inline"><input type="checkbox" ${allChecked?'checked':''} onchange="setVisibleSelection('selectedInventory',S.data.inventory.filter(x=>JSON.stringify(x).toLowerCase().includes((document.getElementById('searchBox').value||'').toLowerCase())),this.checked)"> Pilih semua</label><button class="secondary" onclick="clearSelection('selectedInventory')">Batal Pilih</button><button class="danger" onclick="deleteSelectedInventory()" ${S.selectedInventory.size?'':'disabled'}>Hapus Pilihan (${S.selectedInventory.size})</button><span class="spacer"></span><button class="secondary" onclick="exportExcel('inventory')">Excel</button><button class="secondary" onclick="printList('inventory')">PDF / Print</button><button class="primary" onclick="openInventory()">+ Tambah Stok</button></div><div class="table-wrap"><table><thead><tr><th></th><th>Nama Produk</th><th>Jenis Kayu</th><th>Finishing</th><th>Jumlah</th><th>Lokasi</th></tr></thead><tbody>${a.map(x=>`<tr><td onclick="event.stopPropagation()"><input type="checkbox" ${S.selectedInventory.has(x.id)?'checked':''} onchange="toggleSelection('selectedInventory','${x.id}',this.checked)"></td><td onclick="openInventory('${x.id}')">${esc(x.name)}</td><td onclick="openInventory('${x.id}')">${esc(x.wood)}</td><td onclick="openInventory('${x.id}')">${esc(x.finish)}</td><td onclick="openInventory('${x.id}')"><b>${fmt(x.qty)}</b></td><td onclick="openInventory('${x.id}')">${esc(x.location)}</td></tr>`).join('')||'<tr><td colspan="6" class="note">Belum ada data stok.</td></tr>'}</tbody></table></div>`}
function openInventory(id){const x=id?S.data.inventory.find(a=>a.id===id):{id:uid(),name:'',wood:'',finish:'',qty:0,location:''};modalBody.innerHTML=`<h2>Stok Produk</h2><div class="form-grid"><div class="field"><label>Nama Produk</label><input id="i_name" value="${esc(x.name)}"></div><div class="field"><label>Jenis Kayu</label><input id="i_wood" value="${esc(x.wood)}"></div><div class="field"><label>Finishing</label><input id="i_finish" value="${esc(x.finish)}"></div><div class="field"><label>Jumlah</label><input id="i_qty" type="number" value="${x.qty}"></div><div class="field"><label>Lokasi</label><input id="i_location" value="${esc(x.location)}"></div></div><div class="toolbar" style="margin-top:16px"><button class="primary" onclick="saveInventory('${x.id}',${!!id})">Simpan</button>${id?`<button class="danger" onclick="deleteRecord('inventory','${x.id}')">Hapus</button>`:''}</div>`;openModal()}
async function saveInventory(id,exists){const x={id,name:i_name.value,wood:i_wood.value,finish:i_finish.value,qty:+i_qty.value||0,location:i_location.value};if(exists)S.data.inventory[S.data.inventory.findIndex(a=>a.id===id)]=x;else S.data.inventory.push(x);await persist('Stok disimpan');closeModal();render()}
function allWorkerCompletions(){return [...S.data.completed,...S.data.shipments.flatMap(sh=>sh.items.map(x=>({...x,completedAt:x.completedAt||sh.shippedAt})))]}
function renderWorkers(q=''){meta('DB Pekerja','Riwayat produksi selesai · rekap bulanan jumlah & nilai');const a=S.data.workers.filter(x=>JSON.stringify(x).toLowerCase().includes(q)),all=allWorkerCompletions(),allChecked=a.length&&a.every(x=>S.selectedWorkers.has(x.id));content.innerHTML=`<div class="toolbar"><label class="select-inline"><input type="checkbox" ${allChecked?'checked':''} onchange="setVisibleSelection('selectedWorkers',S.data.workers.filter(x=>JSON.stringify(x).toLowerCase().includes((document.getElementById('searchBox').value||'').toLowerCase())),this.checked)"> Pilih semua</label><button class="secondary" onclick="clearSelection('selectedWorkers')">Batal Pilih</button><button class="danger" onclick="deleteSelectedWorkers()" ${S.selectedWorkers.size?'':'disabled'}>Hapus Pilihan (${S.selectedWorkers.size})</button><span class="spacer"></span><button class="secondary" onclick="exportExcel('workers')">Excel</button><button class="secondary" onclick="printList('workers')">PDF / Print</button><button class="primary" onclick="openWorker()">+ Tambah Pekerja</button></div><div class="grid grid3">${a.map(w=>{const hist=all.filter(c=>c.workerId===w.id);return `<div class="card worker-select-card"><div class="card-check" onclick="event.stopPropagation()"><input class="row-check" type="checkbox" ${S.selectedWorkers.has(w.id)?'checked':''} onchange="toggleSelection('selectedWorkers','${w.id}',this.checked)"></div><div onclick="openWorker('${w.id}')"><b>${esc(w.name)}</b><p class="note">${esc(w.workplace)} · ${esc(w.phone)}</p><span class="badge">Riwayat selesai ${hist.length}</span></div></div>`}).join('')||'<div class="note">Belum ada pekerja.</div>'}</div>`}
function workerMonthOptions(wid){const months=[...new Set(allWorkerCompletions().filter(c=>c.workerId===wid).map(c=>(c.completedAt||'').slice(0,7)).filter(Boolean))].sort().reverse();return months}
function workerMonthSummary(wid,month){const a=allWorkerCompletions().filter(c=>c.workerId===wid&&(!month||(c.completedAt||'').startsWith(month))),m=new Map();for(const c of a){const k=c.productId,prev=m.get(k)||{productId:k,qty:0,amount:0};prev.qty+=+c.totalQty||0;prev.amount+=+c.amount||((+c.unitPrice||0)*(+c.totalQty||0));m.set(k,prev)}return [...m.values()]}
function openWorker(id){const w=id?S.data.workers.find(x=>x.id===id):{id:uid(),name:'',workplace:'',phone:'',note:'',completed:[]};window._workerId=w.id;const months=id?workerMonthOptions(w.id):[],month=months[0]||'';modalBody.innerHTML=`<h2>Detail Pekerja</h2><div class="form-grid"><div class="field"><label>Nama Pekerja</label><input id="w_name" value="${esc(w.name)}"></div><div class="field"><label>Workshop</label><input id="w_place" value="${esc(w.workplace)}"></div><div class="field"><label>Kontak</label><input id="w_phone" value="${esc(w.phone)}"></div><div class="field span2"><label>Catatan</label><textarea id="w_note">${esc(w.note)}</textarea></div></div>${id?`<div class="section-title">Rekap Produksi Bulanan</div><div class="toolbar"><label>Bulan <select id="workerMonth" onchange="drawWorkerHistory('${w.id}')">${months.map(m=>`<option value="${m}">${m}</option>`).join('')||'<option value="">Belum ada riwayat</option>'}</select></label></div><div id="workerHistory"></div>`:''}<div class="toolbar" style="margin-top:16px"><button class="primary" onclick="saveWorker('${w.id}',${!!id})">Simpan</button>${id?`<button class="danger" onclick="deleteRecord('workers','${w.id}')">Hapus</button>`:''}</div>`;openModal();if(id)drawWorkerHistory(w.id)}
function drawWorkerHistory(wid){const month=document.getElementById('workerMonth')?.value||'',sum=workerMonthSummary(wid,month),hist=allWorkerCompletions().filter(c=>c.workerId===wid&&(!month||(c.completedAt||'').startsWith(month))).sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt))),qty=sum.reduce((s,x)=>s+x.qty,0),amount=sum.reduce((s,x)=>s+x.amount,0);workerHistory.innerHTML=`<div class="monthly-metrics"><div class="card metric"><small>Total Produk</small><strong>${fmt(qty)} pcs</strong></div><div class="card metric"><small>Total Nilai Produksi</small><strong>${money(amount)}</strong></div></div><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Produk</th><th>Jumlah</th><th>Nilai Produksi</th></tr></thead><tbody>${sum.map(x=>`<tr><td>${esc(prodName(x.productId))}</td><td>${fmt(x.qty)}</td><td>${money(x.amount)}</td></tr>`).join('')||'<tr><td colspan="3" class="note">Belum ada produksi selesai pada bulan ini.</td></tr>'}</tbody></table></div><div class="section-title">Detail Selesai</div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Produk</th><th>Jumlah</th><th>Harga Satuan</th><th>Jumlah Harga</th><th>Tanggal Selesai</th></tr></thead><tbody>${hist.map(c=>`<tr><td>${esc(c.orderNo||'')}</td><td>${esc(prodName(c.productId))}</td><td>${fmt(c.totalQty)}</td><td>${money(c.unitPrice)}</td><td>${money(c.amount)}</td><td>${new Date(c.completedAt).toLocaleDateString('id-ID')}</td></tr>`).join('')}</tbody></table></div>`}
async function saveWorker(id,exists){const old=S.data.workers.find(x=>x.id===id);const w={id,name:w_name.value,workplace:w_place.value,phone:w_phone.value,note:w_note.value,completed:old?.completed||[]};if(exists)S.data.workers[S.data.workers.findIndex(x=>x.id===id)]=w;else S.data.workers.push(w);await persist('Pekerja disimpan');closeModal();render()}
function openBulkImport(){modalBody.innerHTML=`<h2>Excel + Gambar Massal</h2><div class="bulk-import-card"><div class="bulk-help"><p><b>1.</b> Pilih file Excel, lalu <b>2.</b> pilih semua file gambar yang namanya ditulis di Excel.</p><p class="note">Urutan utama Excel: <b>제품명, 그룹, W, D, H, 무게(g), 수종, 마감, 단가, 이미지, CBM</b>. Jika grup belum ada, akan ditambahkan otomatis. File yang diunduh akan berisi data produk yang saat ini sudah terdaftar.</p></div><div class="toolbar"><button class="secondary" onclick="downloadProductBulkTemplate()">Unduh Form Registrasi + Data Saat Ini</button></div><div class="field"><label>File Excel</label><input id="bulkExcel" type="file" accept=".xlsx,.xls,.csv"></div><div class="field" style="margin-top:12px"><label>File Gambar</label><input id="bulkImages" type="file" accept="image/*" multiple></div><div class="note" style="margin-top:6px">Nama file pada kolom <b>이미지</b> akan dicocokkan dengan file gambar yang dipilih.</div><div class="toolbar" style="margin-top:16px"><button class="primary" onclick="runProductBulkImport()">Jalankan Registrasi Massal</button><button class="secondary" onclick="closeModal()">Batal</button></div></div>`;openModal()}
function makerNamesForExcel(makers=[]){return (makers||[]).map(m=>workerName(m.workerId)).filter(x=>x&&x!=='-').join(';')}
function makerPricesForExcel(makers=[]){return (makers||[]).map(m=>+m.price||0).join(';')}
function downloadProductBulkTemplate(){const headers=['제품명','그룹','W','D','H','무게(g)','수종','마감','단가','이미지','CBM','추가부품','생산자','작업자 단가','상세내용'];let rows=S.data.products.map(p=>({'제품명':p.name,'그룹':p.group||'',W:p.w,D:p.d,H:p.h,'무게(g)':p.weight_g||0,'수종':p.wood||'','마감':p.finish||'','단가':p.unitPrice||0,'이미지':p.imageFileName||imageExportName(p),CBM:p.cbm||0,'추가부품':serializeParts(p.parts),'생산자':makerNamesForExcel(p.makers),'작업자 단가':makerPricesForExcel(p.makers),'상세내용':serializeDetails(p.details,p.detailHtml)}));if(!rows.length)rows=[{'제품명':'Sample Tray','그룹':'TRAY',W:300,D:200,H:25,'무게(g)':650,'수종':'Mahogany','마감':'Oil','단가':35000,'이미지':'tray001.jpg',CBM:0.0015,'추가부품':'Handle:80x20x15:2','생산자':'Budi','작업자 단가':35000,'상세내용':'[TEXT]Catatan penting'}];const ws=XLSX.utils.json_to_sheet(rows,{header:headers}),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'제품DB');XLSX.writeFile(wb,`NAYESO_제품DB_등록양식_${todayCode()}.xlsx`)}
function parsePartsText(v){return String(v||'').split(';').map(x=>x.trim()).filter(Boolean).map(x=>{const a=x.split(':');return{name:a[0]||'',size:a[1]||'',qty:+a[2]||1}})}
function parseMakersText(v){return String(v||'').split(';').map(x=>x.trim()).filter(Boolean).map(x=>{const a=x.split(':'),w=S.data.workers.find(z=>z.name===a[0]);return w?{workerId:w.id,price:+a[1]||0}:null}).filter(Boolean)}
function parseMakersColumns(names,prices){const ns=String(names||'').split(';').map(x=>x.trim()).filter(Boolean),ps=String(prices||'').split(';').map(x=>x.trim());return ns.map((name,i)=>{const w=S.data.workers.find(z=>String(z.name||'').trim().toLowerCase()===name.toLowerCase());return w?{workerId:w.id,price:+(ps[i]||0)||0}:null}).filter(Boolean)}
async function runProductBulkImport(){const xf=document.getElementById('bulkExcel')?.files?.[0];if(!xf)return alert('Pilih file Excel.');const imgs=[...(document.getElementById('bulkImages')?.files||[])],map=new Map(imgs.map(f=>[f.name.trim().toLowerCase(),f]));const data=await xf.arrayBuffer(),wb=XLSX.read(data),rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});let added=0,updated=0,linked=0;for(const r of rows){const name=String(r['제품명']||r['Nama Produk']||'').trim();if(!name)continue;let p=S.data.products.find(x=>x.name===name),isNew=!p;if(!p){p={id:uid(),makers:[],parts:[],details:[],image:'',imageFileName:'',imageSource:''};S.data.products.push(p)}p.name=name;p.group=String(r['그룹']||r['Grup']||'').trim();if(p.group&&!S.data.groups.includes(p.group))S.data.groups.push(p.group);p.w=+(r.W||0);p.d=+(r.D||0);p.h=+(r.H||0);p.weight_g=+(r['무게(g)']||r['Berat(g)']||0);p.cbm=+(r.CBM||0)||((p.w*p.d*p.h)/1e9)||0;p.wood=r['수종']||r['Jenis Kayu']||'';p.finish=r['마감']||r['Finishing']||'';p.unitPrice=+(r['단가']||r['Harga Satuan']||0);if(r['추가부품']!=='')p.parts=parsePartsText(r['추가부품']);else if(!Array.isArray(p.parts))p.parts=[];if(r['생산자']!==''||r['작업자 단가']!=='')p.makers=parseMakersColumns(r['생산자'],r['작업자 단가']);else if(r['생산자/단가']!=='')p.makers=parseMakersText(r['생산자/단가']);else if(!Array.isArray(p.makers))p.makers=[];if(!Array.isArray(p.details))p.details=[];const rawFn=String(r['이미지']||r['제품 이미지']||r['Gambar Utama']||r['대표이미지']||'').trim();const fn=rawFn.toLowerCase();if(rawFn)p.imageFileName=rawFn;if(fn&&map.has(fn)){p.image=await compressImageFile(map.get(fn));p.imageFileName=map.get(fn).name;p.imageSource='excel';linked++}isNew?added++:updated++}await persist('Excel + gambar massal');closeModal();render();alert(`Selesai
Produk baru: ${added}
Diperbarui: ${updated}
Gambar terhubung: ${linked}`)}
async function renderSettings(){
  if(!isAdmin()){S.page='dashboard';render();return}
  meta('Pengaturan','Admin · pengguna login · password · Excel · backup');
  const logs=S.data.logs.slice();
  content.innerHTML=`<div class="grid grid2">
  <div class="card span2"><h3>Nama Login Pekerja</h3><p class="note">Nama di bawah ini muncul pada Login Umum. Menghapus nama login tidak menghapus DB Pekerja atau riwayat produksinya.</p><div id="loginUserManager"></div><button class="primary" style="margin-top:10px" onclick="addLoginUser()">+ Tambah Nama Login</button></div>
  <div class="card"><h3>Password Admin</h3><p class="note">Password awal 1082. Hanya dapat diubah setelah masuk sebagai Admin.</p><div class="field"><label>Password Baru</label><input id="new_admin_password" type="password"></div><div class="field" style="margin-top:8px"><label>Ulangi Password Baru</label><input id="new_admin_password2" type="password"></div><button class="primary" style="margin-top:10px" onclick="changeAdminPassword()">Ubah Password</button></div>
  <div class="card"><h3>Status Sinkronisasi</h3><p class="note">${S.cloud?'Cloud aktif. HP dan PC berbagi data secara real-time.':'Mode lokal. Hubungkan Supabase untuk penggunaan bersama HP/PC.'}</p><div class="badge">${S.cloud?'Real-time aktif':'Lokal'}</div></div>
  <div class="card"><h3>Google Drive · Gambar & Backup</h3><p class="note">Gambar produk/detail dapat disimpan di Google Drive sehingga Storage Supabase tidak cepat penuh. URL dan kode ini hanya diatur Admin satu kali.</p><div class="field"><label>Apps Script Web App URL</label><input id="drive_gateway_url" value="${esc(driveConfig().url)}" placeholder="https://script.google.com/macros/s/.../exec"></div><div class="field" style="margin-top:8px"><label>Kode Koneksi Drive</label><input id="drive_gateway_token" type="password" value="${esc(driveConfig().token)}" placeholder="kode rahasia yang sama dengan Apps Script"></div><div class="toolbar" style="margin-top:10px"><button class="primary" onclick="saveDriveSettings()">Simpan Koneksi Drive</button><button class="secondary" onclick="testDriveConnection()">Tes Koneksi</button></div><div class="badge" style="margin-top:10px">${driveEnabled()?'Drive siap':'Belum terhubung'}</div></div>
  <div class="card"><h3>Impor Excel</h3><div class="field"><label>DB Tujuan</label><select id="excelTarget"><option value="boxes">DB Box</option><option value="workers">DB Pekerja</option><option value="inventory">Stok Produk</option></select></div><div class="toolbar" style="margin-top:10px"><button class="primary" onclick="excelFile.click()">Pilih File Excel</button><button class="secondary" onclick="downloadTemplate()">Unduh Template</button></div><p class="note">Pendaftaran massal DB Produk + gambar tersedia di Akses Cepat pada Beranda.</p></div>
  <div class="card"><h3>Grup Produk</h3><div id="groupManager"></div><button class="primary" style="margin-top:10px" onclick="addGroup()">+ Tambah Grup</button></div>
  <div class="card"><h3>Backup Semua Data</h3><p class="note">Backup lokal tetap tersedia. Jika Google Drive terhubung, backup juga bisa disimpan dan dipulihkan langsung dari folder Backup di Drive.</p><div class="toolbar"><button class="secondary" onclick="exportBackup()">Simpan Backup JSON</button><button class="primary" onclick="importBackup()">Pulihkan Backup JSON</button><button class="secondary" onclick="undoLastRestore()">Batalkan Restore Terakhir</button><button class="primary" onclick="backupToDrive()">Backup ke Google Drive</button><button class="secondary" onclick="openDriveBackups()">Pulihkan dari Google Drive</button></div></div>
  <div class="card span2"><h3>Perubahan 3 Bulan Terakhir</h3><p class="note">Perubahan pekerja menampilkan nama pekerja. Perubahan Admin tidak menampilkan nama. Klik baris untuk melihat isi.</p><div class="activity-list">${logs.map(l=>`<button class="activity-row" onclick="openLogDetail('${l.id}')"><span><b>${esc(l.label)}</b><small>${new Date(l.at).toLocaleString('id-ID')}${l.by?` · ${esc(l.by)}`:''}</small></span><span>›</span></button>`).join('')||'<div class="note">Belum ada perubahan dalam 3 bulan terakhir.</div>'}</div></div>
  </div>`;drawGroupManager();drawLoginUserManager()
}
function drawLoginUserManager(){const el=document.getElementById('loginUserManager');if(!el)return;el.innerHTML=S.data.loginUsers.map((u,i)=>`<div class="repeat-row"><div class="field"><label>Nama</label><input value="${esc(u.name)}" onchange="renameLoginUser(${i},this.value)"></div><div class="field"><label>Status</label><select onchange="toggleLoginUser(${i},this.value==='1')"><option value="1" ${u.active!==false?'selected':''}>Aktif</option><option value="0" ${u.active===false?'selected':''}>Nonaktif</option></select></div><button class="danger" onclick="removeLoginUser(${i})">Hapus</button></div>`).join('')||'<div class="note">Belum ada nama login.</div>'}
async function addLoginUser(){if(!isAdmin())return;const name=prompt('Nama pekerja untuk Login Umum');if(!name?.trim())return;if(S.data.loginUsers.some(x=>x.name.toLowerCase()===name.trim().toLowerCase()))return alert('Nama ini sudah ada.');S.data.loginUsers.push({id:uid(),name:name.trim(),active:true});await persist('Nama login ditambahkan',`Nama login pekerja ditambahkan: ${name.trim()}`);drawLoginUserManager()}
async function renameLoginUser(i,name){if(!isAdmin())return;name=name.trim();if(!name)return drawLoginUserManager();const old=S.data.loginUsers[i]?.name||'';S.data.loginUsers[i].name=name;await persist('Nama login diubah',`${old} → ${name}`);drawLoginUserManager()}
async function toggleLoginUser(i,active){if(!isAdmin())return;const u=S.data.loginUsers[i];u.active=active;await persist('Status login diubah',`${u.name}: ${active?'Aktif':'Nonaktif'}`);drawLoginUserManager()}
async function removeLoginUser(i){if(!isAdmin())return;const u=S.data.loginUsers[i];if(!confirm(`Hapus ${u.name} dari Login Umum?`))return;S.data.loginUsers.splice(i,1);await persist('Nama login dihapus',`Nama login pekerja dihapus: ${u.name}`);drawLoginUserManager()}
async function changeAdminPassword(){if(!isAdmin())return;const a=new_admin_password.value,b=new_admin_password2.value;if(a.length<4)return alert('Password minimal 4 karakter.');if(a!==b)return alert('Password baru tidak sama.');const h=await hashText(a);let cfg=S.data.adminConfig.find(x=>x.id==='admin');if(!cfg){cfg={id:'admin',passwordHash:h};S.data.adminConfig.push(cfg)}else cfg.passwordHash=h;await persist('Password Admin diubah','Password Admin berhasil diubah.');new_admin_password.value='';new_admin_password2.value='';alert('Password Admin sudah diubah. Login berikutnya gunakan password baru.')}
async function saveDriveSettings(){if(!isAdmin())return;const url=(document.getElementById('drive_gateway_url')?.value||'').trim(),token=(document.getElementById('drive_gateway_token')?.value||'').trim();let cfg=S.data.adminConfig.find(x=>x.id==='admin');if(!cfg){cfg={id:'admin',passwordHash:adminHash()};S.data.adminConfig.push(cfg)}cfg.driveUrl=url;cfg.driveToken=token;S.settings.driveUrl=url;S.settings.driveToken=token;localStorage.setItem('nayeso_id_settings',JSON.stringify(S.settings));await persist('Koneksi Google Drive disimpan','Pengaturan Google Drive diperbarui.');alert('Koneksi Google Drive disimpan.');renderSettings()}
async function testDriveConnection(){try{const r=await driveFormRequest('ping');alert(`Google Drive terhubung.\nFolder: ${r.folderName||'NAYESO Indonesia Files'}`)}catch(e){alert('Koneksi Google Drive gagal: '+e.message)}}
async function backupToDrive(){if(!driveEnabled())return alert('Hubungkan Google Drive terlebih dahulu di Pengaturan.');try{const name=`NAYESO_ID_backup_${todayCode()}_${new Date().toTimeString().slice(0,8).replace(/:/g,'')}.json`;const text=JSON.stringify({version:12,exportedAt:new Date().toISOString(),data:S.data},null,2);await driveFormRequest('backup',{fileName:name,text});alert('Backup berhasil disimpan ke Google Drive / Backup.')}catch(e){alert('Backup Drive gagal: '+e.message)}}
async function openDriveBackups(){if(!driveEnabled())return alert('Hubungkan Google Drive terlebih dahulu.');try{const r=await driveFormRequest('listBackups');const files=r.files||[];modalBody.innerHTML=`<h2>Backup Google Drive</h2><p class="note">Pilih backup yang ingin dipulihkan. Data saat ini akan disimpan sebagai cadangan pemulihan lokal terlebih dahulu.</p><div class="activity-list">${files.map(f=>`<button class="activity-row" onclick="restoreDriveBackup('${f.id}')"><span><b>${esc(f.name)}</b><small>${f.updated?new Date(f.updated).toLocaleString('id-ID'):''}</small></span><span>›</span></button>`).join('')||'<div class="note">Belum ada backup di Google Drive.</div>'}</div>`;openModal()}catch(e){alert('Daftar backup tidak dapat dibaca: '+e.message)}}
async function restoreDriveBackup(fileId){if(!confirm('Pulihkan backup Google Drive ini? Data saat ini akan dicadangkan secara lokal terlebih dahulu.'))return;try{const r=await driveFormRequest('getBackup',{fileId});const parsed=JSON.parse(r.text||'{}'),data=parsed.data||parsed;if(!validBackupData(data))throw new Error('Format backup tidak valid');localStorage.setItem('nayeso_id_pre_restore_backup',JSON.stringify({at:new Date().toISOString(),data:S.data}));S.data=data;normalize();await persist('Backup Google Drive dipulihkan');closeModal();render();alert('Backup Google Drive berhasil dipulihkan.')}catch(e){alert('Restore Drive gagal: '+e.message)}}
function openLogDetail(id){const l=S.data.logs.find(x=>x.id===id);if(!l)return;modalBody.innerHTML=`<h2>Detail Perubahan</h2><div class="card"><div><b>${esc(l.label)}</b></div><div class="note" style="margin-top:5px">${new Date(l.at).toLocaleString('id-ID')}${l.by?` · ${esc(l.by)}`:''}</div><div style="margin-top:14px;white-space:pre-wrap">${esc(l.detail||l.label)}</div></div>`;openModal()}
function drawGroupManager(){const el=document.getElementById('groupManager');if(!el)return;el.innerHTML=`<div class="toolbar"><button class="secondary" onclick="S.data.groups.forEach(g=>S.selectedGroups.add(g));drawGroupManager()">Pilih Semua</button><button class="secondary" onclick="S.selectedGroups.clear();drawGroupManager()">Batal Pilih</button><button class="danger" onclick="removeSelectedGroups()" ${S.selectedGroups.size?'':'disabled'}>Hapus Pilihan (${S.selectedGroups.size})</button></div>`+(S.data.groups.map((g,i)=>`<div class="repeat-row"><input class="row-check" type="checkbox" ${S.selectedGroups.has(g)?'checked':''} onchange="this.checked?S.selectedGroups.add('${esc(g)}'):S.selectedGroups.delete('${esc(g)}');drawGroupManager()"><div class="field"><input value="${esc(g)}" onchange="renameGroup(${i},this.value)"></div><button class="secondary" onclick="moveGroup(${i},-1)" ${i===0?'disabled':''}>↑</button><button class="secondary" onclick="moveGroup(${i},1)" ${i===S.data.groups.length-1?'disabled':''}>↓</button><button class="danger" onclick="removeGroup(${i})">Hapus</button></div>`).join('')||'<div class="note">Belum ada grup.</div>')}
async function addGroup(){const name=prompt('Nama grup baru');if(!name?.trim())return;S.data.groups.push(name.trim());await persist('Grup produk ditambahkan');drawGroupManager()}
async function renameGroup(i,name){name=name.trim();if(!name)return;const old=S.data.groups[i];S.data.groups[i]=name;for(const p of S.data.products)if(p.group===old)p.group=name;for(const c of S.data.completed)if(c.group===old)c.group=name;for(const sh of S.data.shipments)for(const x of sh.items)if(x.group===old)x.group=name;await persist('Nama grup diubah');drawGroupManager()}
async function moveGroup(i,dir){const j=i+dir;if(j<0||j>=S.data.groups.length)return;[S.data.groups[i],S.data.groups[j]]=[S.data.groups[j],S.data.groups[i]];await persist('Urutan grup diubah');drawGroupManager()}
async function removeGroup(i){const g=S.data.groups[i];if(!confirm(`Hapus grup ${g}? Produk yang memakai grup ini akan dikosongkan, tetapi riwayat selesai/pengiriman tetap menyimpan nama grup lama.`))return;S.data.groups.splice(i,1);for(const p of S.data.products)if(p.group===g)p.group='';await persist('Grup produk dihapus');drawGroupManager()}
async function removeSelectedGroups(){if(!S.selectedGroups.size)return;const ids=new Set(S.selectedGroups);if(!confirm(`Hapus ${ids.size} grup yang dipilih? Riwayat lama tetap menyimpan nama grupnya.`))return;S.data.groups=S.data.groups.filter(g=>!ids.has(g));for(const p of S.data.products)if(ids.has(p.group))p.group='';S.selectedGroups.clear();await persist('Grup produk terpilih dihapus');drawGroupManager()}
async function setUserActive(id,active){if(!confirm(active?'Setujui akses pengguna ini?':'Blokir akses pengguna ini?'))return;const {error}=await S.supabase.from('profiles').update({active}).eq('id',id);if(error)alert(error.message);else renderSettings()}
async function setUserRole(id,role){if(!confirm(`Ubah hak akses menjadi ${role==='admin'?'Admin':'Pengguna'}?`))return;const {error}=await S.supabase.from('profiles').update({role}).eq('id',id);if(error)alert(error.message);else renderSettings()}
async function saveCloudSettings(){S.settings={url:set_url.value.trim(),key:set_key.value.trim()};localStorage.setItem('nayeso_id_settings',JSON.stringify(S.settings));await connectCloud()}
function openModal(){modal.classList.remove('hidden');requestAnimationFrame(()=>{const c=modal.querySelector('.modal-card');if(c)c.scrollTop=0})}
function closeModal(){modal.classList.add('hidden');window._detailSelectedImage=null}
function modalWheelScroll(e){
  if(modal.classList.contains('hidden'))return;
  const card=modal.querySelector('.modal-card');
  if(!card)return;
  if(Math.abs(e.deltaY)<Math.abs(e.deltaX))return;

  /* 노트북 터치패드/마우스 휠 모두 같은 방식으로 처리 */
  let dy=e.deltaY||0;
  if(e.deltaMode===1)dy*=32;
  else if(e.deltaMode===2)dy*=Math.max(300,window.innerHeight*.85);
  if(!dy)return;

  /* 팝업 안에 포인터가 있으면 팝업 스크롤이 항상 1순위 */
  if(card.contains(e.target)){
    const maxInner=Math.max(0,card.scrollHeight-card.clientHeight);
    const atTop=card.scrollTop<=1;
    const atBottom=card.scrollTop>=maxInner-1;
    const innerCanMove=(dy<0&&!atTop)||(dy>0&&!atBottom);
    if(maxInner>1&&innerCanMove){
      e.preventDefault();
      e.stopPropagation();
      card.scrollTop=Math.max(0,Math.min(maxInner,card.scrollTop+dy));
      return;
    }
    /* 팝업이 끝에 닿으면 preventDefault를 하지 않는다.
       브라우저의 기본 scroll chaining으로 바깥 페이지가 이어서 움직인다. */
    return;
  }

  /* 팝업 바깥의 회색 배경에서는 바깥 페이지의 기본 스크롤을 그대로 허용 */
}
